// For the "Currently exploring" group the detail panel shows an animated in-progress bar.
const EXPLORING_ID = 'exploring'

/* ---------- REAL project links, built from src/data/projects.js (nothing to maintain) ----------
   A tool counts as "used in" a project when it appears in that project's `tech` list.
   ALIASES maps the names used here to the names used in projects.js. */
const ALIASES = {
  'Retrieval-Augmented Generation (RAG)': ['RAG'],
  'RAG Pipelines': ['RAG'],
  'LLM Applications': ['LLMs'],
  'Streamlit Community Cloud': [],
}
const norm = (x) => String(x).toLowerCase()

const demoOf = (p) => {
  const l = (p.links || []).find(([label, url]) => url && url !== '#' && !/github/i.test(label))
  return l ? l[1] : null
}
const brief = (p) => ({
  id: p.id,
  title: p.title,
  cat: p.cat?.[0],
  status: p.status,
  image: p.images?.[0] || null,
  href: demoOf(p),
})

const usedIn = (name) => {
  const keys = [name, ...(ALIASES[name] || [])].map(norm)
  return PROJECTS.filter((p) => (p.tech || []).some((t) => keys.includes(norm(t)))).map(brief)
}

// distinct projects that use at least one tool from the group
const groupProjects = (g) => {
  const seen = new Map()
  g.items.forEach((it) => usedIn(it.name).forEach((p) => seen.set(p.id, p)))
  return [...seen.values()]
}

