const NAME_TO_GLYPH = {
  Matplotlib: 'chart',
  Seaborn: 'chart',
  'VS Code': 'code',
  PowerShell: 'terminal',
  Cursor: 'cursor',
  SQL: 'db',
  'Ridge Regression': 'slope',
  'Model Evaluation': 'gauge',
  'Feature Engineering': 'wrench',
  LLMs: 'brain',
  'Retrieval-Augmented Generation (RAG)': 'search',
  Embeddings: 'nodes',
  'Vector Search': 'vector',
  'Prompt Engineering': 'prompt',
  'AI APIs': 'api',
  'Relational Database Design': 'db',
  'Advanced Machine Learning': 'layers',
  'Deep Learning': 'nodes',
  'LLM Applications': 'spark',
  'RAG Pipelines': 'search',
  'AI Agents': 'agent',
}

const mono = (name) =>
  name
    .replace(/\(.*\)/, '')
    .split(/[\s.-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0])
    .join('')
    .toUpperCase()

/* One component for every tool: brand mark -> concept glyph -> monogram. */
function ToolLogo({ name, className = 'ts-logo' }) {
  if (BRAND[name]) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
        <path d={BRAND[name]} />
      </svg>
    )
  }
  const g = NAME_TO_GLYPH[name]
  if (g && GLYPH[g]) {
    return (
      <svg
        className={className}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
      >
        {GLYPH[g]}
      </svg>
    )
  }
  return (
    <svg className={className} viewBox="0 0 24 24" aria-hidden="true">
      <rect x="2" y="2" width="20" height="20" rx="5" fill="none" stroke="currentColor" strokeWidth="1.6" />
      <text x="12" y="16" textAnchor="middle" fontSize="9" fontWeight="700" fill="currentColor" fontFamily="DM Sans, sans-serif">
        {mono(name)}
      </text>
    </svg>
  )
}

/* ---------- background effects ---------- */
/* ==========================================================================
   BackgroundFX: one canvas behind the Tech Stack section.
   Layers (back to front): drifting orbs, parallax stars (warp streaks + cursor
   push), tool constellation (hover a tool to see what it was used with),
   a different "mood" per group, rising dust, an orbit ring, a bloom behind the
   centred card and a ripple on every group change.

   Reads live values from the `fx` ref that TechStack.jsx keeps up to date:
     fx.current = { pos, warp, dir, active, tint, hover, px, py }
   Lite mode (phones, reduced motion) draws fewer particles or a still frame.
   ========================================================================== */

const TAU = Math.PI * 2
const ease = (x) => x * x * (3 - 2 * x)
const MONO = '12px "DM Mono", ui-monospace, Menlo, Consolas, monospace'

const hash = (str) => {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}
const seeded = (seed) => {
  let a = seed >>> 0
  return () => (a = (Math.imul(a, 1664525) + 1013904223) >>> 0) / 4294967296
}
const hexRgb = (hex) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex || '')
  const n = m ? parseInt(m[1], 16) : 0xd8b4fd
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

// every tool becomes a faint star (stable position from its name)
const NODES = STACK.flatMap((g, gi) =>
  g.items.map((it) => {
    const r = seeded(hash(it.name))
    return { name: it.name, gid: g.id, gi, nx: 0.05 + r() * 0.9, ny: 0.1 + r() * 0.78, z: 0.35 + r() * 0.5 }
  }),
)
const NODE_BY_NAME = Object.fromEntries(NODES.map((n) => [n.name, n]))

function BackgroundFX({ fx, related }) {
  const ref = useRef(null)

  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return undefined
    const ctx = canvas.getContext('2d')
    const host = canvas.closest('.ts')
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    let W = 0
    let H = 0
    let lite = false
    let raf = 0
    let timer = 0
    let t = 0
    let last = performance.now()

    let stars = []
    let dust = []
    let orbs = []
    let glyphs = []
    let tokens = []
    let frames = []
    let beams = []
    let dots = []

    const tint = hexRgb(STACK[0].tint)
    let mood = STACK[fx.current.active || 0].id
    let prevMood = mood
    let moodT = 1
    let lastActive = fx.current.active || 0
    let bloomBoost = 0
    const ripples = []
    let hoverMix = 0
    let hoverName = null

    const build = () => {
      const r = seeded(7)
      stars = Array.from({ length: lite ? 70 : 150 }, () => ({ x: r() * W, y: r() * H, z: 0.2 + r() * 0.8, s: 0.4 + r() * 1.1, ph: r() * TAU, tw: 0.6 + r() * 1.6 }))
      dust = Array.from({ length: lite ? 14 : 40 }, () => ({ x: r() * W, y: r() * H, v: 6 + r() * 14, r: 0.6 + r() * 1.4, ph: r() * TAU }))
      orbs = [
        { x: 0.18, y: 0.3, r: 0.34, z: 0.06, a: 0.1 },
        { x: 0.82, y: 0.64, r: 0.3, z: 0.1, a: 0.08 },
        { x: 0.55, y: 0.12, r: 0.22, z: 0.04, a: 0.07 },
      ]
      glyphs = Array.from({ length: lite ? 14 : 30 }, () => ({ x: r() * W, y: r() * H, v: 10 + r() * 22, ch: '{}<>/;=()[]#'[(r() * 12) | 0] }))
      tokens = Array.from({ length: lite ? 10 : 22 }, () => ({ x: r() * W, y: r() * H, w: 26 + r() * 26, vx: 4 + r() * 8, vy: -2 - r() * 4, ph: r() * TAU }))
      frames = Array.from({ length: lite ? 4 : 8 }, () => ({ x: r() * W, y: r() * H, w: 90 + r() * 90, vx: 3 + r() * 5, vy: 1 + r() * 3 }))
      beams = Array.from({ length: lite ? 8 : 18 }, () => ({ x: r() * W, y: r() * H, len: 40 + r() * 120, v: 60 + r() * 140 }))
      dots = Array.from({ length: lite ? 40 : 70 }, () => ({ sx: r() * W, sy: r() * H, a: r() * TAU, rr: r() }))
    }

    const size = () => {
      const rect = canvas.getBoundingClientRect()
      W = Math.max(1, rect.width)
      H = Math.max(1, rect.height)
      lite = W < 700 || reduced
      const dpr = Math.min(window.devicePixelRatio || 1, lite ? 1 : 1.5)
      canvas.width = Math.round(W * dpr)
      canvas.height = Math.round(H * dpr)
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      build()
    }

    const col = (a) => `rgba(${tint[0] | 0},${tint[1] | 0},${tint[2] | 0},${a})`
    const wrap = (v, m) => ((v % m) + m) % m

    /* ---------- moods: one per group ---------- */
    const drawMood = (id, a, dt) => {
      if (a <= 0.01) return
      ctx.save()
      ctx.globalAlpha = a
      const cx = W / 2
      const cy = H * 0.46
      if (id === 'languages') {
        ctx.font = MONO
        ctx.fillStyle = col(0.2)
        glyphs.forEach((g) => {
          g.y = wrap(g.y + g.v * dt, H)
          ctx.fillText(g.ch, g.x, g.y)
        })
      } else if (id === 'data') {
        const step = lite ? 70 : 46
        for (let y = step / 2; y < H; y += step) {
          for (let x = step / 2; x < W; x += step) {
            const k = Math.sin(x * 0.011 + y * 0.013 - t * 0.9) * 0.5 + 0.5
            ctx.fillStyle = col(0.04 + k * 0.22)
            ctx.beginPath()
            ctx.arc(x, y, 0.8 + k * 1.6, 0, TAU)
            ctx.fill()
          }
        }
      } else if (id === 'ml') {
        const layers = [4, 6, 6, 3]
        const pts = layers.map((n, li) => Array.from({ length: n }, (_, i) => ({ x: W * (0.2 + li * 0.2), y: H * (0.18 + ((i + 0.5) / n) * 0.62) })))
        ctx.lineWidth = 1
        for (let li = 0; li < pts.length - 1; li++) {
          pts[li].forEach((p, i) => {
            pts[li + 1].forEach((q, j) => {
              ctx.strokeStyle = col(0.07)
              ctx.beginPath()
              ctx.moveTo(p.x, p.y)
              ctx.lineTo(q.x, q.y)
              ctx.stroke()
              const ph = wrap(t * 0.35 + i * 0.13 + j * 0.29 + li * 0.4, 1)
              if ((i + j + li) % 3 === 0) {
                ctx.fillStyle = col(0.55 * Math.sin(ph * Math.PI))
                ctx.beginPath()
                ctx.arc(p.x + (q.x - p.x) * ph, p.y + (q.y - p.y) * ph, 1.8, 0, TAU)
                ctx.fill()
              }
            })
          })
        }
        pts.flat().forEach((p) => {
          ctx.fillStyle = col(0.45)
          ctx.beginPath()
          ctx.arc(p.x, p.y, 3, 0, TAU)
          ctx.fill()
        })
      } else if (id === 'ai') {
        tokens.forEach((k) => {
          k.x = wrap(k.x + k.vx * dt, W + 60)
          k.y = wrap(k.y + k.vy * dt, H + 40)
          ctx.strokeStyle = col(0.2)
          ctx.lineWidth = 1
          ctx.beginPath()
          ctx.roundRect(k.x - 30, k.y, k.w, 13, 6)
          ctx.stroke()
          ctx.fillStyle = col(0.3 + 0.2 * Math.sin(t * 1.4 + k.ph))
          ctx.beginPath()
          ctx.arc(k.x - 30 + 8, k.y + 6.5, 2, 0, TAU)
          ctx.fill()
        })
      } else if (id === 'web') {
        ctx.lineWidth = 1
        ctx.strokeStyle = col(0.16)
        frames.forEach((f) => {
          f.x = wrap(f.x + f.vx * dt, W + 200)
          f.y = wrap(f.y + f.vy * dt, H + 140)
          const x = f.x - 100
          const y = f.y - 60
          const h = f.w * 0.62
          ctx.strokeRect(x, y, f.w, h)
          ctx.beginPath()
          ctx.moveTo(x, y + 12)
          ctx.lineTo(x + f.w, y + 12)
          ctx.moveTo(x + 10, y + 26)
          ctx.lineTo(x + f.w * 0.55, y + 26)
          ctx.moveTo(x + 10, y + 38)
          ctx.lineTo(x + f.w * 0.4, y + 38)
          ctx.stroke()
        })
      } else if (id === 'databases') {
        ctx.lineWidth = 1
        ctx.strokeStyle = col(0.06)
        for (let y = 20; y < H; y += 38) {
          ctx.beginPath()
          ctx.moveTo(0, y)
          ctx.lineTo(W, y)
          ctx.stroke()
        }
        for (let x = W * 0.1; x < W; x += W * 0.16) {
          ctx.beginPath()
          ctx.moveTo(x, 0)
          ctx.lineTo(x, H)
          ctx.stroke()
        }
        const sy = wrap(t * 70, H + 120) - 60
        const g = ctx.createLinearGradient(0, sy - 50, 0, sy + 50)
        g.addColorStop(0, col(0))
        g.addColorStop(0.5, col(0.14))
        g.addColorStop(1, col(0))
        ctx.fillStyle = g
        ctx.fillRect(0, sy - 50, W, 100)
      } else if (id === 'devtools') {
        ctx.lineWidth = 1.2
        for (let k = 0; k < 4; k++) {
          const bx = W * (0.08 + k * 0.045)
          ctx.strokeStyle = col(0.12)
          ctx.beginPath()
          ctx.moveTo(bx, 0)
          ctx.bezierCurveTo(bx, H * 0.3, bx + 40 + k * 8, H * 0.5, bx + 40 + k * 8, H)
          ctx.stroke()
          for (let i = 0; i < 6; i++) {
            const py = wrap(i * (H / 6) + t * (14 + k * 4), H)
            const px = bx + (py / H) * (40 + k * 8) * (py / H)
            ctx.fillStyle = col(0.4)
            ctx.beginPath()
            ctx.arc(px, py, 2.4, 0, TAU)
            ctx.fill()
          }
        }
      } else if (id === 'deploy') {
        beams.forEach((b) => {
          b.y -= b.v * dt
          if (b.y + b.len < 0) {
            b.y = H + 20
            b.x = Math.random() * W
          }
          const g = ctx.createLinearGradient(0, b.y, 0, b.y + b.len)
          g.addColorStop(0, col(0.32))
          g.addColorStop(1, col(0))
          ctx.fillStyle = g
          ctx.fillRect(b.x, b.y, 1.5, b.len)
        })
      } else if (id === 'exploring') {
        const cyc = wrap(t, 16) / 16
        const p = cyc < 0.55 ? ease(cyc / 0.55) : cyc < 0.8 ? 1 : 1 - ease((cyc - 0.8) / 0.2)
        const R = Math.min(W, H) * 0.3
        dots.forEach((d, i) => {
          const ang = (i / dots.length) * TAU + t * 0.05
          const tx = cx + Math.cos(ang) * R
          const ty = cy + Math.sin(ang) * R * 0.5
          const x = d.sx + (tx - d.sx) * p
          const y = d.sy + (ty - d.sy) * p
          ctx.fillStyle = col(0.18 + 0.5 * p)
          ctx.beginPath()
          ctx.arc(x, y, 1.4 + d.rr * 1.4, 0, TAU)
          ctx.fill()
        })
      }
      ctx.restore()
    }

    const frame = (now) => {
      raf = requestAnimationFrame(frame)
      const dt = Math.min(0.05, (now - last) / 1000)
      last = now
      if (document.hidden || host?.classList.contains('is-paused')) return
      draw(dt)
    }

    const draw = (dt) => {
      t += dt
      const f = fx.current
      // smooth tint
      const target = hexRgb(STACK[f.active]?.tint)
      for (let i = 0; i < 3; i++) tint[i] += (target[i] - tint[i]) * Math.min(1, dt * 3)

      if (f.active !== lastActive) {
        lastActive = f.active
        prevMood = mood
        mood = STACK[f.active].id
        moodT = 0
        bloomBoost = 1
        ripples.push({ t0: t })
      }
      moodT = Math.min(1, moodT + dt / 0.9)
      bloomBoost = Math.max(0, bloomBoost - dt * 0.8)

      ctx.clearRect(0, 0, W, H)
      const cx = W / 2
      const cy = H * 0.46
      const pos = f.pos
      const warp = f.warp || 0
      const dir = f.dir || 1

      // orbs (depth parallax)
      orbs.forEach((o, i) => {
        const x = wrap(o.x * W - pos * 120 * o.z * 10, W * 1.4) - W * 0.2
        const y = o.y * H + Math.sin(t * 0.15 + i) * 16
        const g = ctx.createRadialGradient(x, y, 0, x, y, o.r * W)
        g.addColorStop(0, col(o.a))
        g.addColorStop(1, col(0))
        ctx.fillStyle = g
        ctx.fillRect(0, 0, W, H)
      })

      // bloom behind the centred card
      const bl = 0.1 + 0.04 * Math.sin(t * 1.4) + bloomBoost * 0.18
      const bg = ctx.createRadialGradient(cx, cy, 0, cx, cy, H * 0.42)
      bg.addColorStop(0, col(bl))
      bg.addColorStop(1, col(0))
      ctx.fillStyle = bg
      ctx.fillRect(0, 0, W, H)

      // stars: parallax with the carousel, streak with speed, pushed by the cursor
      const hasPtr = f.px != null
      stars.forEach((s) => {
        let x = wrap(s.x - pos * 26 * s.z, W)
        let y = s.y
        let a = 0.25 + 0.55 * (0.5 + 0.5 * Math.sin(t * s.tw + s.ph)) * s.z
        if (hasPtr) {
          const dx = x - f.px
          const dy = y - f.py
          const d = Math.hypot(dx, dy)
          if (d < 150 && d > 0.1) {
            const k = 1 - d / 150
            x += (dx / d) * k * 14
            y += (dy / d) * k * 14
            a = Math.min(1, a + k * 0.6)
          }
        }
        ctx.fillStyle = `rgba(255,255,255,${a.toFixed(3)})`
        if (warp > 0.08) {
          const len = warp * s.z * 80
          ctx.fillRect(dir > 0 ? x - len : x, y, len + s.s, s.s * 0.8)
        } else {
          ctx.fillRect(x, y, s.s, s.s)
        }
      })

      // tool constellation: faint group links, strong links for the hovered tool
      const groupNodes = NODES.filter((n) => n.gi === f.active)
      const pnode = (n) => ({ x: wrap(n.nx * W - pos * 18 * n.z, W), y: n.ny * H })
      ctx.lineWidth = 1
      ctx.strokeStyle = col(0.1)
      ctx.beginPath()
      groupNodes.forEach((n, i) => {
        const p = pnode(n)
        if (i === 0) ctx.moveTo(p.x, p.y)
        else ctx.lineTo(p.x, p.y)
      })
      ctx.stroke()
      NODES.forEach((n) => {
        const p = pnode(n)
        const inG = n.gi === f.active
        ctx.fillStyle = inG ? col(0.55) : 'rgba(255,255,255,0.22)'
        ctx.beginPath()
        ctx.arc(p.x, p.y, inG ? 2 : 1.3, 0, TAU)
        ctx.fill()
      })
      if (f.hover) hoverName = f.hover
      hoverMix += ((f.hover ? 1 : 0) - hoverMix) * Math.min(1, dt * 7)
      if (hoverMix > 0.02 && hoverName && NODE_BY_NAME[hoverName]) {
        const src = pnode(NODE_BY_NAME[hoverName])
        const rel = related(hoverName).filter((nm) => NODE_BY_NAME[nm])
        ctx.font = MONO
        rel.forEach((nm) => {
          const q = pnode(NODE_BY_NAME[nm])
          ctx.strokeStyle = col(0.7 * hoverMix)
          ctx.lineWidth = 1.2
          ctx.beginPath()
          ctx.moveTo(src.x, src.y)
          ctx.lineTo(q.x, q.y)
          ctx.stroke()
          ctx.fillStyle = col(0.95 * hoverMix)
          ctx.beginPath()
          ctx.arc(q.x, q.y, 3.4, 0, TAU)
          ctx.fill()
          ctx.fillStyle = `rgba(255,255,255,${(0.8 * hoverMix).toFixed(2)})`
          ctx.fillText(nm, q.x + 8, q.y + 4)
        })
        const sg = ctx.createRadialGradient(src.x, src.y, 0, src.x, src.y, 26)
        sg.addColorStop(0, col(0.8 * hoverMix))
        sg.addColorStop(1, col(0))
        ctx.fillStyle = sg
        ctx.fillRect(src.x - 26, src.y - 26, 52, 52)
        ctx.fillStyle = `rgba(255,255,255,${hoverMix.toFixed(2)})`
        ctx.beginPath()
        ctx.arc(src.x, src.y, 3.6, 0, TAU)
        ctx.fill()
        ctx.fillText(hoverName, src.x + 9, src.y + 4)
      }

      // moods (cross-fade old to new)
      if (moodT < 1) drawMood(prevMood, 1 - ease(moodT), dt)
      drawMood(mood, ease(moodT), dt)

      // dust
      dust.forEach((d) => {
        d.y -= d.v * dt
        if (d.y < -4) {
          d.y = H + 4
          d.x = Math.random() * W
        }
        const x = d.x + Math.sin(t * 0.5 + d.ph) * 10
        ctx.fillStyle = col(0.18 + 0.2 * Math.sin(t + d.ph))
        ctx.beginPath()
        ctx.arc(x, d.y, d.r, 0, TAU)
        ctx.fill()
      })

      // orbit ring with three satellites
      ctx.save()
      ctx.translate(cx, cy + H * 0.05)
      const rx = W * 0.36
      const ry = H * 0.075
      ctx.strokeStyle = col(0.12)
      ctx.lineWidth = 1
      ctx.beginPath()
      ctx.ellipse(0, 0, rx, ry, 0, 0, TAU)
      ctx.stroke()
      for (let i = 0; i < 3; i++) {
        const a = t * 0.22 + (i * TAU) / 3
        const x = Math.cos(a) * rx
        const y = Math.sin(a) * ry
        const g = ctx.createRadialGradient(x, y, 0, x, y, 12)
        g.addColorStop(0, col(0.75))
        g.addColorStop(1, col(0))
        ctx.fillStyle = g
        ctx.fillRect(x - 12, y - 12, 24, 24)
      }
      ctx.restore()

      // ripple on group change
      for (let i = ripples.length - 1; i >= 0; i--) {
        const age = t - ripples[i].t0
        if (age > 1.6) {
          ripples.splice(i, 1)
          continue
        }
        ctx.strokeStyle = col(Math.max(0, 0.38 - age * 0.24))
        ctx.lineWidth = 1.5
        ctx.beginPath()
        ctx.ellipse(cx, cy, age * W * 0.4, age * H * 0.34, 0, 0, TAU)
        ctx.stroke()
      }
    }

    size()
    const ro = new ResizeObserver(size)
    ro.observe(canvas)
    if (reduced) {
      draw(0)
      timer = window.setInterval(() => draw(0), 500) // still frame, refreshed for group colour
    } else {
      raf = requestAnimationFrame(frame)
    }
    return () => {
      cancelAnimationFrame(raf)
      clearInterval(timer)
      ro.disconnect()
    }
  }, [fx, related])

  return <canvas ref={ref} className="ts-fx" aria-hidden="true" />
}

/* ---------- STYLES ---------- */
const CSS = `
/* ==========================================================================
   Tech Stack: curved 3D carousel
   Colours come only from tokens.css: --bg --surface --text --muted --accent
   ========================================================================== */

.ts {
  --ts-fh: var(--font-heading, 'Pixelify Sans', ui-monospace, monospace);
  --ts-fb: var(--font-body, 'DM Sans', system-ui, sans-serif);
  --ts-fm: var(--font-mono, 'DM Mono', ui-monospace, 'SFMono-Regular', Menlo, Consolas, monospace);
  --tint: var(--accent, #d8b4fd);
  --cw: 270px;
  --ch: 415px;

  position: relative;
  height: 100vh;
  height: 100dvh;
  min-height: 580px;
  overflow: hidden;
  isolation: isolate;
  background: var(--bg, #09090b);
  color: var(--text, #fafafa);
  font-family: var(--ts-fb);
  -webkit-user-select: none;
  user-select: none;
}

.ts *,
.ts *::before,
.ts *::after {
  box-sizing: border-box;
}

/* visually hidden, still read by screen readers and search engines */
.ts-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ---------- atmosphere ---------- */

.ts-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.ts-glow {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(55% 42% at 50% 40%, color-mix(in srgb, var(--accent, #d8b4fd) 24%, transparent), transparent 72%),
    radial-gradient(85% 38% at 50% 100%, color-mix(in srgb, var(--accent, #d8b4fd) 16%, transparent), transparent 72%);
}

/* tiny space: soft nebula, three layers of twinkling stars, two rare shooting stars */
.ts-nebula {
  position: absolute;
  inset: -10%;
  background:
    radial-gradient(38% 30% at 16% 26%, color-mix(in srgb, var(--accent, #d8b4fd) 13%, transparent), transparent 70%),
    radial-gradient(34% 28% at 84% 72%, color-mix(in srgb, var(--accent, #d8b4fd) 10%, transparent), transparent 70%),
    radial-gradient(26% 22% at 62% 14%, color-mix(in srgb, var(--text, #fafafa) 5%, transparent), transparent 70%);
  animation: ts-drift 46s ease-in-out infinite alternate;
}
.ts-star {
  position: absolute;
  top: 0;
  left: 0;
  border-radius: 50%;
  pointer-events: none;
}
.ts-star--1 { width: 1px; height: 1px; animation: ts-twinkle 6s ease-in-out infinite alternate; }
.ts-star--2 { width: 2px; height: 2px; animation: ts-twinkle 4.5s ease-in-out -2s infinite alternate; }
.ts-star--3 { width: 2px; height: 2px; animation: ts-twinkle 3.2s ease-in-out -1s infinite alternate; }
@keyframes ts-twinkle { from { opacity: 0.3; } to { opacity: 1; } }
@keyframes ts-drift {
  from { transform: translate3d(-1.5%, -1%, 0) scale(1); }
  to { transform: translate3d(1.5%, 1%, 0) scale(1.06); }
}
.ts-shoot {
  position: absolute;
  top: 10%;
  left: 18%;
  width: 90px;
  height: 1px;
  opacity: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.9));
  transform: rotate(32deg);
  animation: ts-shoot 11s linear 3s infinite;
}
.ts-shoot--b { top: 50%; left: 55%; animation-duration: 15s; animation-delay: 8s; }
@keyframes ts-shoot {
  0% { opacity: 0; transform: translate3d(0, 0, 0) rotate(32deg); }
  2% { opacity: 1; }
  9% { opacity: 0; transform: translate3d(260px, 163px, 0) rotate(32deg); }
  100% { opacity: 0; transform: translate3d(260px, 163px, 0) rotate(32deg); }
}
@media (prefers-reduced-motion: reduce) {
  .ts-star, .ts-nebula { animation: none; }
  .ts-shoot { display: none; }
}

.ts-ray {
  position: absolute;
  top: 0;
  left: 50%;
  width: 1px;
  height: 78%;
  transform-origin: top center;
  background: linear-gradient(to bottom, color-mix(in srgb, var(--accent, #d8b4fd) 90%, transparent), transparent 85%);
  opacity: 0.22;
}
.ts-ray--c { height: 62%; opacity: 0.3; }
.ts-ray--l1 { transform: rotate(-66deg); height: 52%; }
.ts-ray--r1 { transform: rotate(66deg); height: 52%; }
.ts-ray--l2 { transform: rotate(-52deg); height: 40%; opacity: 0.12; }
.ts-ray--r2 { transform: rotate(52deg); height: 40%; opacity: 0.12; }

/* ---------- small top label ---------- */

.ts-label {
  position: absolute;
  top: 1.5rem;
  left: 3rem;
  right: 3rem;
  z-index: 6;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  pointer-events: none;
}
.ts-label__title {
  font-family: var(--ts-fh);
  font-size: 1.25rem;
  color: var(--text, #fafafa);
}
.ts-label__hint {
  font-size: 0.8125rem;
  color: var(--muted, #a1a1aa);
}

/* ---------- stage + ring ---------- */

.ts-stage {
  position: absolute;
  inset: 0;
  z-index: 1;
  perspective: 1500px;
  perspective-origin: 50% 42%;
  touch-action: pan-y; /* vertical swipes still scroll the page */
  cursor: grab;
  outline: none;
}
.ts-stage.is-dragging,
.ts-stage.is-dragging * {
  cursor: grabbing;
}
.ts-stage:focus-visible {
  outline: 1px dashed color-mix(in srgb, var(--accent, #d8b4fd) 70%, transparent);
  outline-offset: -8px;
}

.ts-ring {
  position: absolute;
  left: 0;
  right: 0;
  top: 46%;
  height: 0;
  transform-style: preserve-3d;
}

/* glowing curved line under the cards */
.ts-floor {
  position: absolute;
  left: 50%;
  top: calc(46% + var(--ch) / 2 - 150px);
  width: min(138vw, 1900px);
  height: 300px;
  transform: translateX(-50%);
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--accent, #d8b4fd) 50%, transparent);
  background: radial-gradient(ellipse at 50% 50%, color-mix(in srgb, var(--accent, #d8b4fd) 16%, transparent), transparent 68%);
  box-shadow:
    0 0 36px color-mix(in srgb, var(--accent, #d8b4fd) 28%, transparent),
    inset 0 -34px 70px color-mix(in srgb, var(--accent, #d8b4fd) 14%, transparent);
  clip-path: inset(50% 0 0 0);
  pointer-events: none;
}

/* ---------- cards ---------- */

.ts-card {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--cw);
  height: var(--ch);
  margin: calc(var(--ch) / -2) 0 0 calc(var(--cw) / -2);
  transform-style: preserve-3d;
  will-change: transform, opacity;
  backface-visibility: hidden;
  opacity: 0;
  --on: 0;
}

.ts-card__face {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: calc(var(--cw) * 0.075);
  background: var(--surface, #0e0b16);
  box-shadow: 0 22px 44px -22px rgba(0, 0, 0, 0.7);
}
.ts-card__face::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: radial-gradient(90% 62% at 85% 6%, color-mix(in srgb, var(--tint) 40%, transparent), transparent 62%);
  opacity: calc(0.7 + var(--on) * 0.3);
  pointer-events: none;
}
.ts-card__face::after {
  content: none;
}

/* soft outer glow, brightens on the centred card */
.ts-card__halo {
  position: absolute;
  inset: 0;
  border-radius: calc(var(--cw) * 0.075);
  box-shadow: 0 0 60px color-mix(in srgb, var(--tint) 38%, transparent);
  opacity: calc(var(--on) * 0.7);
  pointer-events: none;
}

.ts-card__art {
  position: absolute;
  inset: 0;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  image-rendering: pixelated;
  opacity: calc(0.2 + var(--on) * 0.25);
  -webkit-mask-image: radial-gradient(75% 58% at 88% 8%, #000 0%, transparent 72%);
  mask-image: radial-gradient(75% 58% at 88% 8%, #000 0%, transparent 72%);
  z-index: 0;
}

.ts-card__scan {
  display: none;
}

.ts-card__glow {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  z-index: 3;
  padding: 1px;
  background: linear-gradient(
    155deg,
    color-mix(in srgb, var(--text, #fafafa) 34%, transparent) 0%,
    color-mix(in srgb, var(--text, #fafafa) 8%, transparent) 38%,
    color-mix(in srgb, var(--tint) 45%, transparent) 100%
  );
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: calc(0.55 + var(--on) * 0.45);
  pointer-events: none;
}

.ts-card__top {
  position: absolute;
  top: 5.5%;
  left: 8%;
  right: 8%;
  display: flex;
  justify-content: space-between;
  font-family: var(--ts-fb);
  z-index: 2;
  font-size: max(10px, calc(var(--cw) * 0.04));
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text, #fafafa);
  opacity: 0.6;
}

.ts-card__title {
  position: absolute;
  left: 8%;
  right: 8%;
  bottom: 6.5%;
  font-family: var(--ts-fh);
  z-index: 2;
  font-size: max(16px, calc(var(--cw) * 0.098));
  line-height: 1.08;
  color: var(--text, #fafafa);
  opacity: calc(1 - var(--on) * 1.4);
}

/* the data readout that appears on the centred card */
.ts-info {
  position: absolute;
  inset: 0;
  z-index: 2;
  padding: 17% 8% 8%;
  display: flex;
  flex-direction: column;
  gap: 0.85em;
  font-family: var(--ts-fb);
  font-size: max(11px, calc(var(--cw) * 0.048));
  font-weight: 500;
  line-height: 1.25;
  color: var(--text, #fafafa);
  opacity: calc(var(--on) * 1.25);
  pointer-events: none;
}
.ts-info::before {
  content: none;
}
.ts-info__row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.8em;
  padding-bottom: 0.7em;
  border-bottom: 1px solid color-mix(in srgb, var(--text, #fafafa) 10%, transparent);
}



.ts-info__k {
  flex: none;
  font-size: 0.78em;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted, #a1a1aa);
}
.ts-info__row--name {
  flex-direction: column;
  align-items: flex-start;
  gap: 0.3em;
}
.ts-info__row--name .ts-info__k {
  display: none;
}
.ts-info__row--name .ts-info__v {
  font-family: var(--ts-fh);
  font-weight: 400;
  font-size: max(18px, calc(var(--cw) * 0.098));
  line-height: 1.08;
  text-align: left;
}
.ts-info__row--stack {
  flex-direction: column;
  align-items: flex-start;
  gap: 0.6em;
  margin-top: auto;
  padding-bottom: 0;
  border-bottom: 0;
}
.ts-info__v {
  text-align: right;
  color: var(--text, #fafafa);
  font-weight: 500;
}
.ts-info__list {
  display: flex;
  flex-flow: row wrap;
  align-items: flex-start;
  justify-content: flex-start;
  text-align: left;
  gap: 0.4em;
}
.ts-info__list > span {
  max-width: 100%;
  padding: 0.28em 0.75em;
  border: 1px solid color-mix(in srgb, var(--tint) 45%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--tint) 12%, transparent);
  font-size: 0.88em;
  line-height: 1.2;
}

/* soft reflection on the "floor" */
.ts-card__mirror {
  display: none;
}


/* ---------- headline (bottom-left) ---------- */

.ts-head {
  position: absolute;
  left: 3rem;
  bottom: 1.25rem;
  z-index: 5;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  max-width: min(34vw, 30rem);
  pointer-events: none;
}
.ts-head__title {
  margin: 0;
  font-weight: 500;
}
.ts-head__mask {
  display: block;
  overflow: hidden;
  padding: 0.1em 0 0.2em;
}
.ts-head__line {
  display: flex;
  align-items: flex-start;
  gap: 0.4em;
  font-family: var(--ts-fh);
  font-size: clamp(1.6rem, 3vw, 3rem);
  line-height: 1.04;
  letter-spacing: -0.01em;
  color: var(--text, #fafafa);
  text-shadow: 0 0 32px color-mix(in srgb, var(--accent, #d8b4fd) 40%, transparent);
  will-change: transform;
}
.ts-arrow {
  flex: none;
  width: 0.7em;
  height: 0.7em;
  margin-top: 0.12em;
  color: var(--accent, #d8b4fd);
}
.ts-head__desc {
  margin: 0;
  width: 16.25rem;
  max-width: 100%;
  font-family: var(--ts-fm);
  font-size: 0.75rem;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--muted, #a1a1aa);
}

/* ---------- index pill + pagination ---------- */

.ts-pill {
  position: absolute;
  left: 50%;
  bottom: 4rem;
  z-index: 10;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.625rem;
  min-width: 7.5rem;
  padding: 0.875rem 1.75rem;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--accent, #d8b4fd) 45%, transparent);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--accent, #d8b4fd) 10%, var(--surface, #18181b)),
    color-mix(in srgb, var(--accent, #d8b4fd) 22%, var(--surface, #18181b))
  );
  -webkit-backdrop-filter: blur(5px);
  backdrop-filter: blur(5px);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--text, #fafafa) 22%, transparent),
    0 0 22px color-mix(in srgb, var(--accent, #d8b4fd) 22%, transparent);
  color: var(--text, #fafafa);
  font-family: var(--ts-fb);
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  transition: opacity 0.15s ease, box-shadow 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}
.ts-pill svg {
  width: 1.25rem;
  height: 1.25rem;
}
.ts-pill:hover {
  box-shadow: 0 0 28px color-mix(in srgb, var(--accent, #d8b4fd) 40%, transparent);
}
.ts-pill:focus-visible {
  outline: 2px solid var(--accent, #d8b4fd);
  outline-offset: 3px;
}
.ts-pill.is-open {
  opacity: 0;
}

.ts-pager {
  position: absolute;
  left: 50%;
  bottom: 1.25rem;
  z-index: 10;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 1rem;
  font-family: var(--ts-fm);
  font-size: 0.8125rem;
  color: var(--text, #fafafa);
}
.ts-pager__count {
  width: 2ch;
  text-align: center;
  font-feature-settings: 'tnum';
}
.ts-pager__items {
  display: flex;
  align-items: center;
  cursor: grab;
  touch-action: none;
}
.ts-pager__items.is-dragging,
.ts-pager__items.is-dragging .ts-tick {
  cursor: grabbing;
}
.ts-tick {
  display: flex;
  align-items: center;
  padding: 0 0.4rem;
  background: none;
  border: 0;
  cursor: pointer;
  transition: padding 0.25s ease;
}
.ts-tick:focus-visible {
  outline: 1px solid var(--text, #fafafa);
  outline-offset: 3px;
  border-radius: 2px;
}
.ts-tick__bar {
  display: block;
  width: 1px;
  height: 1rem;
  border: 1px solid transparent;
  border-radius: 3px;
  background: var(--text, #fafafa);
  opacity: 0.35;
  transition: width 0.35s ease, background-color 0.35s ease, border-color 0.35s ease, opacity 0.35s ease;
}
.ts-tick:hover .ts-tick__bar {
  opacity: 1;
}
.ts-tick.is-active .ts-tick__bar {
  width: 0.75rem;
  background: transparent;
  border-color: var(--accent, #d8b4fd);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent, #d8b4fd) 70%, transparent);
  opacity: 1;
}

/* ---------- index overlay ---------- */

.ts-index {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: ts-fade 0.35s ease both;
}
.ts-index__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: color-mix(in srgb, var(--bg, #09090b) 82%, transparent);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  cursor: pointer;
}
.ts-index__panel {
  position: relative;
  width: min(30rem, calc(100% - 2rem));
  max-height: calc(100% - 4rem);
  overflow: auto;
  padding: 0.5rem;
  border-radius: 1.5rem;
  border: 1px solid color-mix(in srgb, var(--accent, #d8b4fd) 45%, transparent);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--accent, #d8b4fd) 10%, var(--surface, #18181b)),
    color-mix(in srgb, var(--accent, #d8b4fd) 20%, var(--surface, #18181b))
  );
  animation: ts-pop 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.ts-index ol {
  list-style: none;
  margin: 0;
  padding: 0;
}
.ts-index li button {
  width: 100%;
  display: grid;
  grid-template-columns: 2.5rem 1fr auto;
  align-items: center;
  gap: 0.5rem;
  padding: 0.8rem 1rem;
  border: 0;
  border-radius: 1rem;
  background: none;
  color: var(--text, #fafafa);
  text-align: left;
  cursor: pointer;
  transition: background-color 0.25s ease;
}
.ts-index li button:hover,
.ts-index li button:focus-visible {
  background: color-mix(in srgb, var(--accent, #d8b4fd) 16%, transparent);
  outline: none;
}
.ts-index li button.is-active .ts-index__t {
  color: var(--accent, #d8b4fd);
}
.ts-index__n,
.ts-index__c {
  font-family: var(--ts-fm);
  font-size: 0.75rem;
  color: var(--muted, #a1a1aa);
}
.ts-index__t {
  font-family: var(--ts-fh);
  font-size: 1.15rem;
  line-height: 1.1;
}

@keyframes ts-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes ts-pop {
  from { opacity: 0; transform: scale(0.92); }
  to { opacity: 1; transform: scale(1); }
}

/* ---------- tablet + phone ---------- */

@media (max-width: 1024px) {
  .ts-label { left: 2rem; right: 2rem; }
  .ts-head {
    left: 2rem;
    top: 3.75rem;
    bottom: auto;
    gap: 1rem;
    max-width: calc(100% - 4rem);
  }
  .ts-head__line { font-size: clamp(1.5rem, 5vw, 2.25rem); }
  .ts-pill { bottom: 4.75rem; padding: 0.75rem 1.5rem; }
  .ts-pager { bottom: 2rem; }
}

@media (max-width: 640px) {
  .ts-label { left: 1rem; right: 1rem; top: 1.1rem; }
  .ts-label__hint { display: none; }
  .ts-head { left: 1rem; top: 3.25rem; max-width: calc(100% - 2rem); }
  .ts-info { padding: 12% 9%; gap: 0.4em; }
  .ts-info__row--name { display: none; }
  .ts-tick { padding: 0 0.3rem; }
}

@media (prefers-reduced-motion: reduce) {
  .ts-index,
  .ts-index__panel { animation: none; }
  .ts-tick,
  .ts-tick__bar,
  .ts-pill { transition: none; }
}


/* ==========================================================================
   UPGRADE LAYER: colour per group, logos, dock, detail panel, search, grid
   ========================================================================== */

@property --ga { syntax: '<color>'; inherits: true; initial-value: #d8b4fd; }

.ts {
  --ga: #d8b4fd;
  --accent: var(--ga);
  --tx: 0; --ty: 0; --gx: 50%; --gy: 50%; --warp: 0;
  transition: --ga 0.9s ease;
}
.ts :focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }
.ts.is-paused *, .ts.is-paused *::before, .ts.is-paused *::after { animation-play-state: paused !important; }

.ts-skip { position: absolute; left: 1rem; top: -4rem; z-index: 40; padding: .6rem 1rem; border-radius: 999px; background: var(--accent); color: var(--bg); font-weight: 600; font-size: .85rem; }
.ts-skip:focus { top: 1rem; }

.ts-logo { width: 1.1em; height: 1.1em; flex: none; display: block; }

/* readability bumps */
.ts-label__hint { font-size: .875rem; color: color-mix(in srgb, var(--text) 62%, var(--muted)); transition: opacity .6s; }
.ts-label__hint.is-gone { opacity: 0; }
.ts-info__k { font-size: .85em; }
.ts-head__desc { font-size: .8125rem; color: color-mix(in srgb, var(--text) 55%, var(--muted)); }
.ts-pager__count { font-size: .875rem; }
.ts-ray { opacity: calc(.22 + var(--warp) * .5); }
.ts-ray--l2, .ts-ray--r2 { opacity: calc(.12 + var(--warp) * .4); }

/* ---- top bar ---- */
.ts-label { align-items: center; }
.ts-label__left { display: flex; align-items: baseline; gap: 1rem; min-width: 0; }
.ts-label__stats { font-family: var(--ts-fm); font-size: .75rem; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); white-space: nowrap; }
.ts-label__right { display: flex; align-items: center; gap: .75rem; pointer-events: auto; min-width: 0; }
.ts-search { position: relative; display: flex; align-items: center; gap: .5rem; padding: 0 .9rem; height: 2.5rem; border-radius: 999px; border: 1px solid color-mix(in srgb, var(--accent) 35%, transparent); background: color-mix(in srgb, var(--surface) 80%, transparent); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); transition: border-color .25s, box-shadow .25s; }
.ts-search:focus-within { border-color: var(--accent); box-shadow: 0 0 18px color-mix(in srgb, var(--accent) 30%, transparent); }
.ts-search svg { width: 1rem; height: 1rem; color: var(--muted); flex: none; }
.ts-search input { width: 8.5rem; background: none; border: 0; outline: none; color: var(--text); font: inherit; font-size: .875rem; user-select: text; -webkit-user-select: text; }
.ts-search input::placeholder { color: var(--muted); }
.ts-search input::-webkit-search-cancel-button { display: none; }
.ts-search__n { font-family: var(--ts-fm); font-size: .7rem; color: var(--accent); white-space: nowrap; }

.ts-iconbtn { display: inline-flex; align-items: center; justify-content: center; min-width: 2.75rem; height: 2.75rem; padding: 0 .5rem; border-radius: 999px; color: var(--text); transition: background-color .25s, opacity .25s, box-shadow .25s; }
.ts-iconbtn svg { width: 1.15rem; height: 1.15rem; }
.ts-iconbtn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent) 18%, transparent); }
.ts-iconbtn:disabled { opacity: .25; cursor: default; }
.ts-copy { height: 2.5rem; min-width: 2.5rem; border: 1px solid color-mix(in srgb, var(--accent) 35%, transparent); background: color-mix(in srgb, var(--surface) 80%, transparent); }
.ts-copy__t { font-size: .75rem; padding: 0 .35rem; color: var(--accent); white-space: nowrap; }
.ts-auto.is-on { color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }

/* segmented control */
.ts-seg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 999px; background: color-mix(in srgb, var(--text) 7%, transparent); }
.ts-seg button { padding: .3rem .65rem; border-radius: 999px; font-size: .72rem; font-weight: 500; color: var(--muted); transition: background-color .2s, color .2s; white-space: nowrap; }
.ts-seg button:hover { color: var(--text); }
.ts-seg button.is-on { background: color-mix(in srgb, var(--accent) 28%, transparent); color: var(--text); }

/* level meter */
.ts-meter { display: inline-flex; gap: 2px; align-items: flex-end; flex: none; }
.ts-meter i { width: 4px; height: 12px; border-radius: 2px; background: color-mix(in srgb, var(--text) 16%, transparent); }
.ts-meter i:nth-child(1) { height: 6px; } .ts-meter i:nth-child(2) { height: 8px; } .ts-meter i:nth-child(3) { height: 10px; }
.ts-meter i.on { background: var(--accent); box-shadow: 0 0 8px color-mix(in srgb, var(--accent) 60%, transparent); }

/* ---- tool dock (left, desktop) ---- */
.ts-dock { position: absolute; left: 3rem; top: 6rem; z-index: 7; width: 17.5rem; display: none; flex-direction: column; gap: .75rem; }
.ts-dock__head { display: flex; flex-direction: column; gap: .6rem; align-items: flex-start; }
.ts-dock__kind { font-family: var(--ts-fm); font-size: .75rem; letter-spacing: .1em; text-transform: uppercase; color: var(--accent); }
.ts-dock__list { list-style: none; display: flex; flex-direction: column; gap: 4px; }
.ts-dock__list li { animation: ts-slide .55s var(--ease-out, cubic-bezier(.16,1,.3,1)) both; animation-delay: calc(var(--i) * 55ms); }
.ts-dock__item { width: 100%; display: flex; align-items: center; gap: .7rem; padding: .55rem .75rem; border-radius: .9rem; border: 1px solid transparent; text-align: left; color: var(--text); font-size: .9375rem; background: color-mix(in srgb, var(--surface) 55%, transparent); -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px); transition: background-color .25s, border-color .25s, opacity .25s, transform .25s; }
.ts-dock__item:hover { transform: translateX(4px); background: color-mix(in srgb, var(--accent) 14%, var(--surface)); }
.ts-dock__item.is-sel { border-color: color-mix(in srgb, var(--accent) 60%, transparent); background: color-mix(in srgb, var(--accent) 18%, var(--surface)); }
.ts-dock__item.is-dim { opacity: .28; }
.ts-dock__item.is-hit { border-color: var(--accent); box-shadow: 0 0 16px color-mix(in srgb, var(--accent) 40%, transparent); }
.ts-dock__logo { color: var(--accent); width: 1.25rem; height: 1.25rem; }
.ts-dock__name { flex: 1; min-width: 0; line-height: 1.2; }
@keyframes ts-slide { from { opacity: 0; transform: translateX(-14px); } to { opacity: 1; transform: none; } }

/* ---- detail panel ---- */
.ts-detail { position: absolute; z-index: 8; right: 3rem; top: 5.5rem; width: 18rem; display: none; flex-direction: column; gap: .8rem; padding: 1.1rem 1.2rem 1.2rem; border-radius: 1.25rem; border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); background: linear-gradient(160deg, color-mix(in srgb, var(--accent) 14%, var(--surface)), color-mix(in srgb, var(--surface) 92%, transparent)); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); box-shadow: 0 0 40px color-mix(in srgb, var(--accent) 16%, transparent); }
.ts-detail__x { position: absolute; top: .5rem; right: .5rem; width: 2.25rem; height: 2.25rem; display: none; align-items: center; justify-content: center; }
.ts-detail__x svg { width: 1rem; height: 1rem; }
.ts-detail__top { display: flex; align-items: center; gap: .9rem; animation: ts-fade .45s ease both; }
.ts-detail__logo { width: 3.25rem; height: 3.25rem; flex: none; display: grid; place-items: center; border-radius: 1rem; color: var(--accent); background: color-mix(in srgb, var(--accent) 16%, transparent); border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); }
.ts-detail__logo .ts-logo { width: 1.7rem; height: 1.7rem; }
.ts-detail__name { font-family: var(--ts-fh); font-weight: 500; font-size: 1.35rem; line-height: 1.1; margin: 0; }
.ts-detail__group { margin: .2rem 0 0; font-size: .78rem; color: var(--muted); }
.ts-detail__level { display: flex; align-items: center; gap: .6rem; font-size: .85rem; }
.ts-detail__lv { font-weight: 600; color: var(--accent); }
.ts-detail__hint { color: var(--muted); }
.ts-detail__note { margin: 0; font-size: .9375rem; line-height: 1.45; color: color-mix(in srgb, var(--text) 85%, var(--muted)); }
.ts-detail__meta { list-style: none; display: flex; flex-wrap: wrap; gap: .4rem; font-size: .75rem; color: var(--muted); }
.ts-detail__meta li { padding: .2rem .6rem; border-radius: 999px; border: 1px solid color-mix(in srgb, var(--text) 14%, transparent); }
.ts-progress { height: 4px; border-radius: 4px; overflow: hidden; background: color-mix(in srgb, var(--text) 10%, transparent); }
.ts-progress i { display: block; width: 40%; height: 100%; border-radius: 4px; background: linear-gradient(90deg, transparent, var(--accent), transparent); animation: ts-prog 1.8s ease-in-out infinite; }
@keyframes ts-prog { from { transform: translateX(-100%); } to { transform: translateX(250%); } }

@media (min-width: 1100px) { .ts-dock { display: flex; } .ts-detail { display: flex; } }

/* ---- cards: logos, emblem, tilt, shine, sweep, depth of field ---- */
.ts-card__face { transform: perspective(900px) rotateX(calc(var(--ty) * -5deg * var(--on))) rotateY(calc(var(--tx) * 6deg * var(--on))); transition: transform .25s ease-out; filter: blur(calc((1 - var(--on)) * 1.3px)); animation: ts-float 7s ease-in-out infinite alternate; }
@keyframes ts-float { from { translate: 0 -3px; } to { translate: 0 4px; } }
.ts-card__emblem { position: absolute; top: 5%; right: 7%; width: 46%; aspect-ratio: 1; z-index: 0; color: var(--tint); opacity: calc(.14 + var(--on) * .16); pointer-events: none; -webkit-mask-image: linear-gradient(200deg, #000 20%, transparent 85%); mask-image: linear-gradient(200deg, #000 20%, transparent 85%); }
.ts-card__emblem .ts-logo { width: 100%; height: 100%; }
.ts-card__shine { position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: calc(var(--on) * .9); background: radial-gradient(circle at var(--gx) var(--gy), rgba(255,255,255,.16), transparent 42%); mix-blend-mode: screen; }
.ts-card__sweep { position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: 0; background: linear-gradient(105deg, transparent 35%, rgba(255,255,255,.22) 50%, transparent 65%); transform: translateX(-120%); }
.ts-card.is-active .ts-card__sweep { animation: ts-sweep 1.1s .15s ease-out 1 both; }
@keyframes ts-sweep { 0% { opacity: 1; transform: translateX(-120%); } 100% { opacity: 0; transform: translateX(120%); } }
.ts-card__title { font-size: max(15px, calc(var(--cw) * .092)); }

.ts-chip { display: inline-flex; align-items: center; gap: .4em; max-width: 100%; padding: .28em .7em .28em .55em; border: 1px solid color-mix(in srgb, var(--tint) 45%, transparent); border-radius: 999px; background: color-mix(in srgb, var(--tint) 12%, transparent); font-size: .88em; line-height: 1.2; pointer-events: auto; cursor: pointer; transition: transform .2s, background-color .25s, opacity .25s, box-shadow .25s; }
.ts-chip__logo { width: 1em; height: 1em; color: var(--tint); }
.ts-chip:hover { transform: translateY(-2px); background: color-mix(in srgb, var(--tint) 24%, transparent); }
.ts-chip.is-sel { background: color-mix(in srgb, var(--tint) 30%, transparent); border-color: var(--tint); }
.ts-chip.is-dim { opacity: .3; }
.ts-chip.is-hit { border-color: var(--text); box-shadow: 0 0 14px color-mix(in srgb, var(--tint) 70%, transparent); }
.ts-card.is-active .ts-chip { animation: ts-chip-in .55s var(--ease-out, cubic-bezier(.16,1,.3,1)) both; animation-delay: calc(var(--i) * 60ms + .2s); }
@keyframes ts-chip-in { from { opacity: 0; transform: translateY(8px) scale(.94); } to { opacity: 1; transform: none; } }
.ts-info__list > span { padding: 0; border: 0; background: none; }

/* ---- CTA, hint, pager ---- */
.ts-cta { position: absolute; right: 3rem; bottom: 1.5rem; z-index: 6; display: none; align-items: center; gap: .6rem; padding: .7rem 1.2rem; border-radius: 999px; border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); font-size: .875rem; font-weight: 500; transition: background-color .25s, box-shadow .25s; }
.ts-cta svg { width: 1rem; height: 1rem; color: var(--accent); transition: transform .25s; }
.ts-cta:hover { background: color-mix(in srgb, var(--accent) 16%, transparent); box-shadow: 0 0 22px color-mix(in srgb, var(--accent) 28%, transparent); }
.ts-cta:hover svg { transform: translateX(3px); }
@media (min-width: 1100px) { .ts-cta { display: inline-flex; } }
.ts-hint { display: none; position: absolute; left: 50%; bottom: 8.4rem; transform: translateX(-50%); z-index: 9; padding: .35rem .8rem; border-radius: 999px; font-size: .75rem; color: var(--muted); border: 1px dashed color-mix(in srgb, var(--accent) 40%, transparent); transition: opacity .6s; pointer-events: none; }
.ts-hint.is-gone { opacity: 0; }
@media (max-width: 1099px) { .ts-hint { display: block; } }

.ts-pager { gap: .35rem; }
.ts-tick { min-height: 2.75rem; padding: 0 .5rem; }
.ts-roll { animation: ts-roll .45s var(--ease-out, cubic-bezier(.16,1,.3,1)); }
@keyframes ts-roll { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ---- index: logos, list/grid ---- */
.ts-index__panel { width: min(32rem, calc(100% - 2rem)); transition: width .3s ease; }
.ts-index__panel.is-grid { width: min(60rem, calc(100% - 2rem)); }
.ts-index__bar { display: flex; align-items: center; justify-content: space-between; gap: .75rem; padding: .5rem .75rem .75rem 1rem; }
.ts-index__title { font-family: var(--ts-fh); font-size: 1.1rem; margin-right: auto; }
.ts-index li button { grid-template-columns: 2.25rem 1fr auto; padding: .7rem 1rem; }
.ts-index__main { display: flex; flex-direction: column; gap: .35rem; min-width: 0; }
.ts-index__logos { display: flex; gap: .55rem; color: var(--tint, var(--accent)); opacity: .85; font-size: .95rem; }
.ts-index li button.is-active .ts-index__t { color: var(--tint, var(--accent)); }
.ts-index__n, .ts-index__c { font-size: .8rem; }
.ts-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr)); gap: .6rem; padding: 0 .5rem .5rem; }
.ts-grid__tile { display: flex; flex-direction: column; gap: .8rem; padding: 1rem; border-radius: 1.1rem; text-align: left; color: var(--text); border: 1px solid color-mix(in srgb, var(--tint) 30%, transparent); background: color-mix(in srgb, var(--tint) 8%, var(--surface)); transition: transform .25s, border-color .25s, background-color .25s; }
.ts-grid__tile:hover, .ts-grid__tile:focus-visible, .ts-grid__tile.is-active { transform: translateY(-2px); border-color: var(--tint); background: color-mix(in srgb, var(--tint) 16%, var(--surface)); }
.ts-grid__h { display: flex; align-items: baseline; gap: .6rem; }
.ts-grid__tools { display: flex; flex-wrap: wrap; gap: .4rem; }
.ts-grid__tool { display: inline-flex; align-items: center; gap: .35rem; padding: .22rem .6rem; border-radius: 999px; font-size: .78rem; border: 1px solid color-mix(in srgb, var(--text) 14%, transparent); }
.ts-grid__tool .ts-logo { color: var(--tint); width: .95em; height: .95em; }

/* ---- tablet + phone ---- */
@media (max-width: 1099px) {
  .ts-label__stats { display: none; }
  .ts-detail { display: flex; left: 1rem; right: 1rem; width: auto; top: auto; bottom: 7.5rem; transform: translateY(130%); opacity: 0; pointer-events: none; transition: transform .45s var(--ease-out, cubic-bezier(.16,1,.3,1)), opacity .3s; z-index: 30; }
  .ts-detail.is-open { transform: none; opacity: 1; pointer-events: auto; }
  .ts-detail__x { display: inline-flex; }
}
@media (max-width: 640px) {
  .ts-label { top: .75rem; }
  .ts-label__title { display: none; }
  .ts-label__right { width: 100%; justify-content: space-between; }
  .ts-search { flex: 1; } .ts-search input { width: 100%; min-width: 0; }
  .ts-label__hint { display: none; }
  .ts-head { top: 4.25rem; }
  .ts-pager { gap: 0; bottom: 1rem; }
  .ts-pager__count { display: none; }
  .ts-auto { display: none; }
  .ts-pill { bottom: 4.5rem; }
  .ts-index__bar { flex-wrap: wrap; }
  .ts-info { padding-top: 21%; }
  .ts-info__row:not(.ts-info__row--stack) { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .ts-card__face, .ts-card__sweep, .ts-chip, .ts-dock__list li, .ts-roll, .ts-progress i { animation: none !important; }
  .ts-card__face { transition: none; }
}

/* ==========================================================================
   MATCH THE WORK SECTION: big pixel numerals, gradient looks, intro heading,
   full-screen light panel, project links and screenshots
   ========================================================================== */

/* ---- intro heading (same scale and voice as "Selected Work") ---- */
.ts-intro { position: absolute; left: 3rem; top: 1.5rem; z-index: 6; max-width: 31rem; pointer-events: none; }
.ts-intro__h { font: 600 clamp(38px, 4.4vw, 62px)/1 var(--ts-fh); letter-spacing: -.01em; margin: 0; }
.ts-intro__p { margin: .7rem 0 0; max-width: 27rem; color: var(--muted); font-size: 1rem; line-height: 1.4; }
.ts-intro .ts-label__stats { display: block; margin-top: .8rem; }
.ts-label { justify-content: flex-end; }
.ts-dock { top: 14rem; }
@media (min-width: 1100px) and (max-height: 840px) {
  .ts-intro__p, .ts-intro .ts-label__stats { display: none; }
  .ts-dock { top: 8.5rem; }
}
@media (max-width: 1099px) {
  .ts-intro { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }
}

/* ---- cards: Work-style gradient looks + giant pixel numeral ---- */
.ts-card[data-look]   { --g1x: 78%; --g1y: 18%; --g1a: 62%; --g2x: 96%; --g2y: 96%; --g2a: 30%; }
.ts-card[data-look="1"] { --g1x: 88%; --g1y: 62%; --g1a: 58%; --g2x: 60%; --g2y: 6%;  --g2a: 28%; }
.ts-card[data-look="2"] { --g1x: 55%; --g1y: 20%; --g1a: 56%; --g2x: 94%; --g2y: 90%; --g2a: 32%; }
.ts-card[data-look="3"] { --g1x: 92%; --g1y: 30%; --g1a: 54%; --g2x: 70%; --g2y: 100%; --g2a: 30%; }
.ts-card__face {
  background:
    radial-gradient(circle at var(--g1x) var(--g1y), color-mix(in srgb, var(--tint) var(--g1a), transparent), transparent 58%),
    radial-gradient(circle at var(--g2x) var(--g2y), color-mix(in srgb, var(--tint) var(--g2a), transparent), transparent 55%),
    linear-gradient(135deg, color-mix(in srgb, var(--tint) 9%, var(--bg)), var(--surface));
}
.ts-card__face::before { content: none; }
.ts-card__art { opacity: calc(.1 + var(--on) * .14); }
.ts-card__num { position: absolute; right: 7%; top: 1%; z-index: 1; font: 600 clamp(54px, calc(var(--cw) * .4), 128px)/1.2 var(--ts-fh); opacity: calc(.15 - var(--on) * .04); pointer-events: none; color: var(--text); }
.ts-card__emblem { top: 30%; right: auto; left: 50%; width: 64%; transform: translateX(-50%); opacity: calc(.07 + var(--on) * .07); -webkit-mask-image: none; mask-image: none; }
.ts-card__top { justify-content: flex-start; font-size: max(10px, calc(var(--cw) * .042)); opacity: .85; z-index: 2; }
.ts-card__title { font-size: max(16px, calc(var(--cw) * .1)); letter-spacing: -.02em; }
.ts-info { padding-top: 15%; }
.ts-info__row--name .ts-info__v { font-size: max(20px, calc(var(--cw) * .104)); }

/* ---- dock count badge, detail extras ---- */
.ts-dock__used { flex: none; min-width: 1.45rem; height: 1.45rem; padding: 0 .3rem; display: grid; place-items: center; border-radius: 999px; font-family: var(--ts-fm); font-size: .7rem; color: var(--bg); background: var(--accent); }
.ts-detail__used { display: flex; flex-direction: column; gap: .45rem; }
.ts-detail__lb, .ts-panel__lb { font-family: var(--ts-fm); font-size: .7rem; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }
.ts-detail__chips { display: flex; flex-wrap: wrap; gap: .4rem; }
.ts-pchip { display: inline-flex; align-items: center; gap: .35rem; padding: .3rem .7rem; border-radius: 999px; font-size: .78rem; font-weight: 500; color: var(--bg); background: var(--accent); transition: transform .25s, box-shadow .25s; }
.ts-pchip:hover { transform: translateY(-2px); box-shadow: 0 6px 18px color-mix(in srgb, var(--accent) 40%, transparent); }
.ts-detail__open { display: inline-flex; align-items: center; justify-content: space-between; gap: .6rem; width: 100%; padding: .7rem 1rem; border-radius: 999px; font-size: .8rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; border: 1px solid color-mix(in srgb, var(--accent) 50%, transparent); transition: background-color .25s, color .25s; }
.ts-detail__open svg { width: 1rem; height: 1rem; transition: transform .25s; }
.ts-detail__open:hover { background: var(--accent); color: var(--bg); }
.ts-detail__open:hover svg { transform: translateX(3px); }

/* ---- full-screen group panel (light, like the Work project panel) ---- */
.ts-ov { position: fixed; inset: 0; z-index: 500; opacity: 0; transition: opacity .3s; }
.ts-ov.is-show { opacity: 1; }
.ts-ov__bg { position: absolute; inset: 0; background: color-mix(in srgb, var(--bg) 78%, transparent); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.ts-panel {
  position: absolute; inset: 16px; overflow: auto; overscroll-behavior: contain;
  background: var(--text); color: var(--bg); border-radius: 26px; padding: 48px;
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr); gap: 56px; align-content: start;
  transform: translateY(48px) scale(.985); transition: transform .55s cubic-bezier(.23, 1, .32, 1);
  user-select: text; -webkit-user-select: text; cursor: auto;
}
.is-show .ts-panel { transform: none; }
.ts-panel :focus-visible { outline-color: var(--bg); }
.ts-panel__x { position: fixed; top: 32px; right: 32px; z-index: 2; width: 48px; height: 48px; border-radius: 50%; background: var(--bg); color: var(--text); font-size: 18px; transition: background .3s, color .3s; }
.ts-panel__x:hover { background: var(--tint); color: var(--bg); }
.ts-panel__l { display: flex; flex-direction: column; align-items: flex-start; min-width: 0; animation: ts-in .6s cubic-bezier(.23,1,.32,1) both; }
.ts-panel__k { font-family: var(--ts-fm); font-size: .75rem; letter-spacing: .1em; text-transform: uppercase; color: color-mix(in srgb, var(--bg) 58%, var(--text)); }
.ts-panel__h { margin: .6rem 0 0; font: 600 clamp(34px, 4.4vw, 62px)/1 var(--ts-fh); letter-spacing: -.01em; }
.ts-panel__d { margin: 1.4rem 0 0; font-size: 1.2rem; line-height: 1.4; letter-spacing: -.01em; max-width: 28rem; }
.ts-panel__mix { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: 1.4rem; }
.ts-pill2 { padding: .5rem .85rem; border-radius: 999px; background: color-mix(in srgb, var(--bg) 8%, var(--text)); font-size: .7rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.ts-pill2--hot { background: var(--bg); color: var(--text); }
.ts-panel__lb { margin-top: 2rem; color: color-mix(in srgb, var(--bg) 58%, var(--text)); }
.ts-panel__proj { display: grid; grid-template-columns: repeat(auto-fill, minmax(11rem, 1fr)); gap: .8rem; width: 100%; margin-top: .7rem; }
.ts-shot { position: relative; display: block; overflow: hidden; aspect-ratio: 16 / 10; border-radius: 12px; background: linear-gradient(135deg, color-mix(in srgb, var(--tint) 40%, var(--bg)), var(--surface)); color: var(--text); transition: transform .3s; }
.ts-shot:hover { transform: translateY(-3px); }
.ts-shot img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.ts-shot__t { position: absolute; left: 0; right: 0; bottom: 0; display: flex; justify-content: space-between; gap: .5rem; padding: 1.4rem .8rem .6rem; font-size: .8rem; font-weight: 600; background: linear-gradient(transparent, rgba(0,0,0,.78)); }
.ts-panel__r { list-style: none; display: flex; flex-direction: column; min-width: 0; }
.ts-trow { display: grid; grid-template-columns: 3rem minmax(0, 1fr) auto; gap: 1rem; align-items: center; padding: 1.1rem 0; border-top: 1px solid color-mix(in srgb, var(--bg) 14%, transparent); animation: ts-in .6s cubic-bezier(.23,1,.32,1) both; animation-delay: calc(var(--i) * 60ms + .1s); }
.ts-trow__logo { width: 3rem; height: 3rem; display: grid; place-items: center; border-radius: 14px; background: color-mix(in srgb, var(--bg) 8%, var(--text)); }
.ts-trow__logo .ts-logo { width: 1.5rem; height: 1.5rem; }
.ts-trow__main { display: flex; flex-direction: column; gap: .2rem; min-width: 0; }
.ts-trow__name { font: 500 clamp(1.15rem, 1.8vw, 1.6rem)/1.15 var(--ts-fh); letter-spacing: -.01em; }
.ts-trow__note { color: color-mix(in srgb, var(--bg) 62%, var(--text)); font-size: .95rem; }
.ts-trow__used { display: flex; flex-wrap: wrap; gap: .35rem; margin-top: .45rem; }
.ts-trow__used .ts-pill2 { padding: .3rem .65rem; font-size: .62rem; }
.ts-trow__lv { display: flex; flex-direction: column; align-items: flex-end; gap: .35rem; font-size: .72rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.ts-panel .ts-meter i { background: color-mix(in srgb, var(--bg) 16%, transparent); box-shadow: none; }
.ts-panel .ts-meter i.on { background: var(--bg); }
@keyframes ts-in { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }

@media (max-width: 900px) {
  .ts-panel { grid-template-columns: 1fr; gap: 32px; padding: 76px 22px 28px; inset: 10px; border-radius: 20px; }
  .ts-panel__x { top: 22px; right: 22px; }
}
@media (prefers-reduced-motion: reduce) {
  .ts-panel, .ts-ov { transition: none; }
  .ts-panel__l, .ts-trow { animation: none; }
}

/* ==========================================================================
   THIN GLOWING CARD BORDERS (colour follows each group's tint)
   ========================================================================== */
.ts-card__glow {
  padding: 1px;
  background: linear-gradient(
    155deg,
    color-mix(in srgb, var(--tint) 95%, #fff) 0%,
    color-mix(in srgb, var(--tint) 30%, transparent) 38%,
    color-mix(in srgb, var(--tint) 75%, transparent) 100%
  );
  opacity: calc(.6 + var(--on) * .4);
}
.ts-card__halo {
  opacity: calc(.3 + var(--on) * .7);
  box-shadow:
    0 0 14px color-mix(in srgb, var(--tint) 45%, transparent),
    0 0 52px color-mix(in srgb, var(--tint) 34%, transparent);
}
.ts-card__face { box-shadow: inset 0 0 26px color-mix(in srgb, var(--tint) calc(8% + var(--on) * 10%), transparent), 0 22px 44px -22px rgba(0, 0, 0, .7); }
.ts-card.is-active .ts-card__halo { animation: ts-pulse 3.6s ease-in-out infinite alternate; }
@keyframes ts-pulse { from { filter: brightness(.85); } to { filter: brightness(1.35); } }
@media (prefers-reduced-motion: reduce) { .ts-card.is-active .ts-card__halo { animation: none; } }
.ts-card__glow { padding: 1.5px; opacity: calc(.75 + var(--on) * .25); }
.ts-card__halo { box-shadow: 0 0 18px color-mix(in srgb, var(--tint) 60%, transparent), 0 0 70px color-mix(in srgb, var(--tint) 42%, transparent); }

/* ==========================================================================
   BACKGROUND UPGRADE: canvas FX, grid floor, group watermark, edge fades, grain
   ========================================================================== */
.ts-fx { position: absolute; inset: 0; width: 100%; height: 100%; display: block; pointer-events: none; }

.ts-nebula {
  translate: calc(var(--np, 0) * -1px) 0;
  background:
    radial-gradient(38% 30% at 16% 26%, color-mix(in srgb, var(--accent) 22%, transparent), transparent 70%),
    radial-gradient(34% 28% at 84% 72%, color-mix(in srgb, var(--accent) 17%, transparent), transparent 70%),
    radial-gradient(26% 22% at 62% 14%, color-mix(in srgb, var(--text) 5%, transparent), transparent 70%);
}

/* perspective grid on the floor (same idea as the Work section) */
.ts-gridfloor {
  position: absolute; left: -30%; right: -30%; top: 63%; height: 62%;
  background-image:
    linear-gradient(color-mix(in srgb, var(--accent) 22%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--accent) 22%, transparent) 1px, transparent 1px);
  background-size: 64px 64px;
  transform: perspective(900px) rotateX(70deg); transform-origin: top;
  -webkit-mask-image: linear-gradient(#000, transparent 82%); mask-image: linear-gradient(#000, transparent 82%);
  opacity: .8;
}

/* huge slow-turning symbol of the active group, far behind everything */
.ts-bgmark {
  position: absolute; left: 50%; top: 44%; width: 74vmin; height: 74vmin; color: var(--accent);
  transform: translate(-50%, -50%);
  animation: ts-spin 140s linear infinite, ts-markin 1.2s ease both;
}
.ts-bgmark .ts-logo { width: 100%; height: 100%; }
@keyframes ts-spin { from { transform: translate(-50%, -50%) rotate(0); } to { transform: translate(-50%, -50%) rotate(360deg); } }
@keyframes ts-markin { from { opacity: 0; } to { opacity: .05; } }

/* soft edges so the section blends into the ones above and below */
.ts-edge { position: absolute; left: 0; right: 0; pointer-events: none; }

.ts-grain { position: absolute; inset: 0; pointer-events: none; opacity: .035; background-size: 170px 170px;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3CfeColorMatrix type='saturate' values='0'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E"); }

@media (max-width: 700px) {
  .ts-gridfloor { opacity: .5; }
  .ts-bgmark { width: 90vmin; height: 90vmin; }
  .ts-shoot--b { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .ts-bgmark { animation: none; opacity: .05; }
}

/* ==========================================================================
   FIX: dark strip above the centred card.
   The face used to tilt and float on its own while the glow stayed still, so a
   gap showed between them. Now the glow and the face move together in one body.
   ========================================================================== */
.ts-card__body {
  position: absolute; inset: 0;
  transform: perspective(900px) rotateX(calc(var(--ty) * -5deg * var(--on))) rotateY(calc(var(--tx) * 6deg * var(--on)));
  transition: transform .25s ease-out;
  filter: blur(calc((1 - var(--on)) * 1.3px));
  animation: ts-float 7s ease-in-out infinite alternate;
}
.ts-card__face { transform: none; transition: none; filter: none; animation: none; }
@media (prefers-reduced-motion: reduce) {
  .ts-card__body { animation: none; transition: none; }
}


/* ==========================================================================
   DARK MATCH: makes Tech Stack as dark as About / Work / Contact.
   Part A dims the glows in the main view. Part B turns the light group panel dark.
   To go back to the old look, delete this whole block (or just Part A or Part B).
   ========================================================================== */

/* ---- Part A: main view (much dimmer glows, same layout) ---- */
.ts-glow {
  background:
    radial-gradient(55% 42% at 50% 40%, color-mix(in srgb, var(--accent, #d8b4fd) 4%, transparent), transparent 72%),
    radial-gradient(85% 38% at 50% 100%, color-mix(in srgb, var(--accent, #d8b4fd) 2.5%, transparent), transparent 72%);
}
.ts-nebula {
  background:
    radial-gradient(38% 30% at 16% 26%, color-mix(in srgb, var(--accent) 4%, transparent), transparent 70%),
    radial-gradient(34% 28% at 84% 72%, color-mix(in srgb, var(--accent) 3%, transparent), transparent 70%),
    radial-gradient(26% 22% at 62% 14%, color-mix(in srgb, var(--text) 1%, transparent), transparent 70%);
}
.ts-gridfloor {
  background-image:
    linear-gradient(color-mix(in srgb, var(--accent) 5%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--accent) 5%, transparent) 1px, transparent 1px);
  opacity: .5;
}
.ts-ray { opacity: .05; }
.ts-ray--c { opacity: .08; }
.ts-ray--l2, .ts-ray--r2 { opacity: .03; }
.ts-fx { opacity: .35; }
.ts-grain { opacity: .02; }
@keyframes ts-markin { from { opacity: 0; } to { opacity: .018; } }
.ts-bgmark { opacity: .018; }
.ts-floor {
  border-color: color-mix(in srgb, var(--accent, #d8b4fd) 14%, transparent);
  background: radial-gradient(ellipse at 50% 50%, color-mix(in srgb, var(--accent, #d8b4fd) 2%, transparent), transparent 68%);
  box-shadow:
    0 0 24px color-mix(in srgb, var(--accent, #d8b4fd) 4%, transparent),
    inset 0 -34px 70px color-mix(in srgb, var(--accent, #d8b4fd) 2%, transparent);
}
.ts-card__face::before { background: radial-gradient(90% 62% at 85% 6%, color-mix(in srgb, var(--tint) 9%, transparent), transparent 62%); }
.ts-card__face { box-shadow: inset 0 0 18px color-mix(in srgb, var(--tint) calc(1.5% + var(--on) * 3%), transparent), 0 22px 44px -22px rgba(0, 0, 0, .9); }
.ts-card__halo { box-shadow: 0 0 10px color-mix(in srgb, var(--tint) 16%, transparent), 0 0 40px color-mix(in srgb, var(--tint) 8%, transparent); }
.ts-card__glow {
  background: linear-gradient(155deg, color-mix(in srgb, var(--tint) 42%, transparent) 0%, color-mix(in srgb, var(--tint) 9%, transparent) 38%, color-mix(in srgb, var(--tint) 30%, transparent) 100%);
  opacity: calc(.5 + var(--on) * .3);
}
.ts-card__art { opacity: calc(.12 + var(--on) * .14); }
.ts-card__shine { background: radial-gradient(circle at var(--gx) var(--gy), rgba(255, 255, 255, .04), transparent 42%); }
.ts-card__sweep { background: linear-gradient(105deg, transparent 35%, rgba(255, 255, 255, .05) 50%, transparent 65%); }

/* ---- Part B: group panel (was off-white, now dark like the rest) ---- */
.ts-ov__bg { background: color-mix(in srgb, var(--bg) 88%, transparent); }
.ts-panel { background: var(--surface); color: var(--text); border: 1px solid color-mix(in srgb, var(--text) 10%, transparent); }
.ts-panel :focus-visible { outline-color: var(--accent); }
.ts-panel__x { background: color-mix(in srgb, var(--text) 8%, var(--surface)); color: var(--text); border: 1px solid color-mix(in srgb, var(--text) 16%, transparent); }
.ts-panel__x:hover { background: var(--accent); color: var(--bg); border-color: var(--accent); }
.ts-panel__k, .ts-panel__lb, .ts-trow__note { color: var(--muted); }
.ts-pill2 { background: color-mix(in srgb, var(--text) 8%, transparent); border: 1px solid color-mix(in srgb, var(--text) 12%, transparent); }
.ts-pill2--hot { background: color-mix(in srgb, var(--accent) 20%, transparent); border-color: color-mix(in srgb, var(--accent) 55%, transparent); color: var(--text); }
.ts-trow { border-top-color: color-mix(in srgb, var(--text) 10%, transparent); }
.ts-trow__logo { background: color-mix(in srgb, var(--text) 7%, transparent); color: var(--accent); }
.ts-panel .ts-meter i { background: color-mix(in srgb, var(--text) 16%, transparent); }
.ts-panel .ts-meter i.on { background: var(--accent); box-shadow: 0 0 8px color-mix(in srgb, var(--accent) 50%, transparent); }

`

/* ---------- SECTION ---------- */
/* ==========================================================================
   TechStack: curved 3D carousel + tool dock, detail panel, search, grid view.
   Content : src/data/techStack.js      (edit tools, levels, notes here)
   Styles  : ./techStack.css            (colours come from tokens.css)
   Logos   : ./logos.js + ./ToolLogo.jsx
   Needs   : react + gsap only.
   ========================================================================== */

/* ---------- named constants (no magic numbers below) ---------- */
const N = STACK.length
const TOTAL_TOOLS = STACK.reduce((n, g) => n + g.items.length, 0)
const RING_RADIUS_K = 3.3 // ring radius = card width * this
const CARD_GAP_K = 1.12 // card spacing along the ring = card width * this
const MAX_VISIBLE = 5.4 // cards further than this (in slots) are hidden
const AUTOPLAY_MS = 4200
const SESSION_KEY = 'ts-last-group'

// real project links, computed once from src/data/projects.js
const USED = Object.fromEntries(STACK.flatMap((g) => g.items.map((it) => [it.name, usedIn(it.name)])))
const GROUP_PROJECTS = STACK.map(groupProjects)
// tools that share a shipped project with `name` (drives the hover constellation)
const PROJ_TOOLS = {}
STACK.forEach((g) => g.items.forEach((it) => USED[it.name].forEach((p) => (PROJ_TOOLS[p.id] = [...(PROJ_TOOLS[p.id] || []), it.name]))))
const relatedTools = (name) => {
  const out = new Set()
  USED[name]?.forEach((p) => PROJ_TOOLS[p.id].forEach((n) => n !== name && out.add(n)))
  if (!out.size) STACK.forEach((g) => g.items.some((it) => it.name === name) && g.items.forEach((it) => it.name !== name && out.add(it.name)))
  return [...out]
}
const PROJECT_COUNT = new Set(GROUP_PROJECTS.flat().map((p) => p.id)).size

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v))
const pad = (n) => String(n).padStart(2, '0')
const prefersReduced = () =>
  typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches
const dur = (s) => (prefersReduced() ? 0 : s)

/* ---------- pixel art per group (cached, tinted with the group colour) ---------- */
const hexToRgb = (hex) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex || '')
  if (!m) return [216, 180, 253]
  const n = parseInt(m[1], 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}
const ART_CACHE = new Map()
function pixelArt(seed, rgb) {
  if (typeof document === 'undefined') return ''
  const key = seed + rgb.join(',')
  if (ART_CACHE.has(key)) return ART_CACHE.get(key)
  let h = 2166136261
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  const rand = () => {
    h += 0x6d2b79f5
    let t = h
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  const W = 26
  const H = 40
  const c = document.createElement('canvas')
  c.width = W
  c.height = H
  const ctx = c.getContext('2d')
  const half = W / 2
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < half; x++) {
      const dx = 1 - x / half
      const dy = Math.abs(y / H - 0.5) * 2
      const density = clamp(1.08 - Math.hypot(dx * 0.95, dy * 0.8), 0, 1)
      if (rand() < density * 0.9) {
        const a = 0.14 + rand() * 0.8 * density
        ctx.fillStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a.toFixed(3)})`
        ctx.fillRect(x, y, 1, 1)
        ctx.fillRect(W - 1 - x, y, 1, 1)
      }
    }
  }
  for (let i = 0; i < 9; i++) {
    ctx.fillStyle = 'rgba(255,255,255,0.85)'
    ctx.fillRect((rand() * W) | 0, (rand() * H) | 0, 1, 1)
  }
  const url = c.toDataURL()
  ART_CACHE.set(key, url)
  return url
}

/* ---------- text "decode" effect ---------- */
const GLYPHS = '▮▯░▒▓/\\<>_-+*#'
function decode(el, text, { duration = 0.6, delay = 0 } = {}) {
  if (!el) return
  if (el._decode) el._decode.kill()
  if (prefersReduced()) {
    el.textContent = text
    return
  }
  const noise = (reveal) => {
    let out = ''
    for (let i = 0; i < text.length; i++) {
      const ch = text[i]
      out += i < reveal || ch === ' ' ? ch : GLYPHS[(Math.random() * GLYPHS.length) | 0]
    }
    return out
  }
  el.textContent = noise(0)
  const s = { p: 0 }
  el._decode = gsap.to(s, {
    p: 1,
    duration,
    delay,
    ease: 'none',
    onUpdate: () => {
      el.textContent = noise(Math.floor(s.p * text.length))
    },
    onComplete: () => {
      el.textContent = text
    },
  })
}

const T = ({ t, className }) => (
  <span className={className} data-decode data-text={t}>
    {t}
  </span>
)

const Icon = ({ d, children }) => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    {d ? <path d={d} /> : children}
  </svg>
)

const Arrow = () => (
  <svg className="ts-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="m15 10 5 5-5 5" />
    <path d="M4 4v7a4 4 0 0 0 4 4h12" />
  </svg>
)

/* level bars: 4 segments, filled = LEVELS[level].bars */
const Meter = ({ level }) => (
  <span className={`ts-meter ts-meter--${level}`} aria-hidden="true">
    {[1, 2, 3, 4].map((n) => (
      <i key={n} className={n <= LEVELS[level].bars ? 'on' : ''} />
    ))}
  </span>
)

/* start group: sessionStorage first, then a #tech-stack-<id> link */
function readStart() {
  try {
    const m = /^#tech-stack-([a-z]+)$/.exec(window.location.hash)
    if (m) {
      const i = STACK.findIndex((g) => g.id === m[1])
      if (i >= 0) return i
    }
    const s = Number(window.sessionStorage.getItem(SESSION_KEY))
    if (Number.isInteger(s) && s >= 0 && s < N) return s
  } catch (e) {
    /* storage can be blocked: start at the first group */
  }
  return 0
}

/* ------------------------------------------------------------------ */
/*  component                                                          */
/* ------------------------------------------------------------------ */

export default function TechStack() {
  const rootRef = useRef(null)
  const stageRef = useRef(null)
  const ringRef = useRef(null)
  const cardsRef = useRef([])
  const headRef = useRef(null)
  const tickRef = useRef(null)
  const bgRef = useRef(null)
  const panelRef = useRef(null)
  const pillRef = useRef(null)
  const hoverRef = useRef(false)

  const start = useRef(readStart())
  const P = useRef({ pos: start.current }) // carousel position 0..N-1 (float while moving)
  const S = useRef({ spread: 0 }) // 0 = stacked, 1 = fanned out (entrance)
  const geo = useRef({ R: 900, step: 0.34, pitch: 300 })
  const drag = useRef({ on: false })
  const chase = useRef({ target: start.current, follow: false, goal: start.current })
  const tickDrag = useRef({ on: false, last: -1 })
  const warp = useRef({ last: start.current, v: 0 })
  const fx = useRef({ pos: start.current, warp: 0, dir: 1, active: start.current, hover: null, px: null, py: null })

  const [active, setActive] = useState(start.current)
  const [dragging, setDragging] = useState(false)
  const [scrubbing, setScrubbing] = useState(false)
  const [indexOpen, setIndexOpen] = useState(false)
  const [indexMode, setIndexMode] = useState('list') // 'list' | 'grid'
  const [query, setQuery] = useState('')
  const [filter, setFilter] = useState('all')
  const [sel, setSel] = useState(null) // selected tool name
  const [auto, setAuto] = useState(false)
  const [used, setUsed] = useState(false)
  const [copied, setCopied] = useState('')
  const [groupOpen, setGroupOpen] = useState(false) // full-screen group panel
  const [panelShown, setPanelShown] = useState(false)
  const ovRef = useRef(null)
  const openerRef = useRef(null)

  const arts = useMemo(() => STACK.map((g) => pixelArt(g.id, hexToRgb(g.tint))), [])
  const q = query.trim().toLowerCase()
  const passes = useCallback(
    (it) => (filter === 'all' || it.level === filter) && (!q || it.name.toLowerCase().includes(q)),
    [filter, q],
  )
  const touch = useCallback(() => setUsed(true), [])

  /* ---------- placement of every card on the curved ring ---------- */
  const render = useCallback(() => {
    const pos = P.current.pos
    const spread = S.current.spread
    const { R, step } = geo.current
    const cards = cardsRef.current

    for (let i = 0; i < cards.length; i++) {
      const el = cards[i]
      if (!el) continue
      const d = i - pos
      const ad = Math.abs(d)
      if (ad > MAX_VISIBLE) {
        if (!el._hidden) {
          el.style.visibility = 'hidden'
          el._hidden = true
        }
        continue
      }
      if (el._hidden) {
        el.style.visibility = 'visible'
        el._hidden = false
      }
      const a = d * step * spread
      const x = Math.sin(a) * R
      const z = -R * (1 - Math.cos(a))
      const deg = (a * 180) / Math.PI
      const fade = clamp(1 - Math.max(0, ad - 2.8) * 0.4, 0, 1) * clamp(spread * 1.3, 0, 1)
      const on = clamp(1 - ad, 0, 1)
      el.style.transform = `translate3d(${x.toFixed(2)}px,0,${z.toFixed(2)}px) rotateY(${deg.toFixed(3)}deg) scale(${(0.9 + 0.1 * spread).toFixed(3)})`
      el.style.opacity = fade.toFixed(3)
      el.style.zIndex = String(100 - Math.round(ad * 10))
      el.style.pointerEvents = ad < 4.6 ? 'auto' : 'none'
      el.style.setProperty('--on', on.toFixed(3))
    }

    // warp: stars slide with the carousel, rays brighten with speed
    const w = warp.current
    w.v += (clamp(Math.abs(pos - w.last) * 5, 0, 1) - w.v) * 0.25
    if (pos !== w.last) fx.current.dir = pos > w.last ? 1 : -1
    w.last = pos
    fx.current.pos = pos
    fx.current.warp = w.v
    const root = rootRef.current
    if (root) root.style.setProperty('--warp', w.v.toFixed(3))
    if (root) root.style.setProperty('--np', (pos * 18).toFixed(1))

    const idx = clamp(Math.round(pos), 0, N - 1)
    setActive((prev) => (prev === idx ? prev : idx))
  }, [])

  const goTo = useCallback(
    (i, { duration = 1.15 } = {}) => {
      const t = clamp(Math.round(i), 0, N - 1)
      const d = dur(duration)
      chase.current.follow = false
      chase.current.goal = t
      gsap.to(P.current, {
        pos: t,
        duration: d,
        ease: 'back.out(0.7)', // small spring overshoot when it lands
        overwrite: true,
        onUpdate: render,
        onComplete: render,
      })
      if (d === 0) render()
    },
    [render],
  )

  const step = useCallback((dir) => goTo(chase.current.goal + dir), [goTo])

  /* ---------- size + geometry ---------- */
  useEffect(() => {
    const measure = () => {
      const w = window.innerWidth
      const cw = w < 640 ? 128 : w < 1024 ? 168 : Math.min(240, Math.max(190, w * 0.115))
      const R = cw * RING_RADIUS_K
      const st = (cw * CARD_GAP_K) / R
      geo.current = { R, step: st, pitch: R * st }
      const root = rootRef.current
      if (root) {
        root.style.setProperty('--cw', `${cw}px`)
        root.style.setProperty('--ch', `${Math.round(cw / 0.65)}px`)
      }
      render()
    }
    measure()
    window.addEventListener('resize', measure)
    return () => window.removeEventListener('resize', measure)
  }, [render])

  /* ---------- entrance + pause everything while off-screen ---------- */
  useEffect(() => {
    const root = rootRef.current
    if (!root) return undefined
    let entered = false
    const io = new IntersectionObserver(
      ([entry]) => {
        root.classList.toggle('is-paused', !entry.isIntersecting)
        if (!entry.isIntersecting || entered) return
        entered = true
        gsap.to(S.current, {
          spread: 1,
          duration: dur(1.6),
          ease: 'power3.out',
          onUpdate: render,
          onComplete: render,
        })
      },
      { threshold: 0.3 },
    )
    io.observe(root)
    return () => io.disconnect()
  }, [render])

  /* ---------- eased following (drag + wheel) ---------- */
  useEffect(() => {
    const tick = (time, deltaTime) => {
      const t = chase.current
      if (!t.follow) return
      const p = P.current
      const k = prefersReduced() ? 1 : 1 - Math.exp(-(deltaTime / 1000) * 13)
      const next = p.pos + (t.target - p.pos) * k
      p.pos = Math.abs(t.target - next) < 0.0004 ? t.target : next
      render()
    }
    gsap.ticker.add(tick)
    return () => gsap.ticker.remove(tick)
  }, [render])

  /* ---------- sideways wheel / trackpad swipe ---------- */
  useEffect(() => {
    const el = stageRef.current
    if (!el) return undefined
    let timer
    const onWheel = (e) => {
      const horizontal = Math.abs(e.deltaX) > Math.abs(e.deltaY) || e.shiftKey
      if (!horizontal) return
      e.preventDefault()
      setUsed(true)
      const delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY
      gsap.killTweensOf(P.current)
      const t = chase.current
      if (!t.follow) t.target = P.current.pos
      t.follow = true
      t.target = clamp(t.target + delta / 300, -0.3, N - 0.7)
      clearTimeout(timer)
      timer = setTimeout(() => goTo(chase.current.target, { duration: 0.9 }), 140)
    }
    el.addEventListener('wheel', onWheel, { passive: false })
    return () => {
      el.removeEventListener('wheel', onWheel)
      clearTimeout(timer)
    }
  }, [goTo])

  /* ---------- mouse: ring parallax + tilt and shine on the centred card ---------- */
  useEffect(() => {
    const root = rootRef.current
    const ring = ringRef.current
    if (!root || !ring || prefersReduced()) return undefined
    const rx = gsap.quickTo(ring, 'rotationX', { duration: 0.9, ease: 'power3.out' })
    const ry = gsap.quickTo(ring, 'rotationY', { duration: 0.9, ease: 'power3.out' })
    const move = (e) => {
      if (e.pointerType !== 'mouse') return
      const r = root.getBoundingClientRect()
      fx.current.px = e.clientX - r.left
      fx.current.py = e.clientY - r.top
      const nx = (e.clientX - r.left) / r.width - 0.5
      const ny = (e.clientY - r.top) / r.height - 0.5
      ry(nx * -4)
      rx(ny * 3)
      const card = cardsRef.current[Math.round(P.current.pos)]
      if (card) {
        const c = card.getBoundingClientRect()
        const px = clamp((e.clientX - c.left) / c.width, 0, 1)
        const py = clamp((e.clientY - c.top) / c.height, 0, 1)
        root.style.setProperty('--tx', ((px - 0.5) * 2).toFixed(3))
        root.style.setProperty('--ty', ((py - 0.5) * 2).toFixed(3))
        root.style.setProperty('--gx', `${(px * 100).toFixed(1)}%`)
        root.style.setProperty('--gy', `${(py * 100).toFixed(1)}%`)
      }
    }
    const leave = () => {
      fx.current.px = null
      fx.current.py = null
      ry(0)
      rx(0)
      root.style.setProperty('--tx', '0')
      root.style.setProperty('--ty', '0')
    }
    root.addEventListener('pointermove', move)
    root.addEventListener('pointerleave', leave)
    return () => {
      root.removeEventListener('pointermove', move)
      root.removeEventListener('pointerleave', leave)
    }
  }, [])

  /* ---------- when the active group changes ---------- */
  useEffect(() => {
    const head = headRef.current
    if (head) {
      const line = head.querySelector('.ts-head__line')
      const desc = head.querySelector('.ts-head__desc')
      gsap.fromTo(line, { yPercent: 115 }, { yPercent: 0, duration: dur(0.85), ease: 'expo.out' })
      gsap.fromTo(desc, { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: dur(0.6), delay: dur(0.12), ease: 'power3.out' })
    }
    const card = cardsRef.current[active]
    if (card) {
      card.querySelectorAll('[data-decode]').forEach((el, i) => decode(el, el.dataset.text, { duration: 0.55, delay: i * 0.035 }))
    }
    fx.current.active = active
    const g = STACK[active]
    setSel((prev) => (prev && g.items.some((it) => it.name === prev) ? prev : (g.items.find((it) => it.name === g.lead) || g.items[0]).name))
    chase.current.goal = active
    try {
      window.sessionStorage.setItem(SESSION_KEY, String(active))
    } catch (e) {
      /* ignore */
    }
  }, [active])

  /* ---------- search: jump to the first group that has a match ---------- */
  useEffect(() => {
    if (!q) return undefined
    const id = setTimeout(() => {
      const here = STACK[chase.current.goal]
      if (here.items.some((it) => it.name.toLowerCase().includes(q))) return
      const i = STACK.findIndex((g) => g.items.some((it) => it.name.toLowerCase().includes(q)))
      if (i >= 0) goTo(i, { duration: 0.9 })
    }, 280)
    return () => clearTimeout(id)
  }, [q, goTo])

  /* ---------- autoplay (off by default; pauses on hover, drag and while the index is open) ---------- */
  useEffect(() => {
    if (!auto) return undefined
    const id = setInterval(() => {
      if (hoverRef.current || drag.current.on || indexOpen) return
      goTo((chase.current.goal + 1) % N)
    }, AUTOPLAY_MS)
    return () => clearInterval(id)
  }, [auto, indexOpen, goTo])

  /* ---------- index dialog: focus in, keys, focus out ---------- */
  useEffect(() => {
    if (!indexOpen) return undefined
    const panel = panelRef.current
    const focusables = () => Array.from(panel.querySelectorAll('button:not([disabled])'))
    const first = panel.querySelector('.is-active') || focusables()[0]
    first?.focus()
    const onKey = (e) => {
      if (e.key === 'Escape') {
        setIndexOpen(false)
        return
      }
      const list = focusables()
      const at = list.indexOf(document.activeElement)
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
        e.preventDefault()
        list[(at + 1) % list.length]?.focus()
      } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
        e.preventDefault()
        list[(at - 1 + list.length) % list.length]?.focus()
      } else if (e.key === 'Tab') {
        e.preventDefault()
        list[(at + (e.shiftKey ? -1 : 1) + list.length) % list.length]?.focus()
      }
    }
    window.addEventListener('keydown', onKey)
    const pill = pillRef.current
    return () => {
      window.removeEventListener('keydown', onKey)
      pill?.focus({ preventScroll: true })
    }
  }, [indexOpen, indexMode])

  /* ---------- full-screen group panel: fade in, keys, focus in and out ---------- */
  useEffect(() => {
    if (!groupOpen) return undefined
    const id = requestAnimationFrame(() => setPanelShown(true))
    const ov = ovRef.current
    const focusables = () => Array.from(ov.querySelectorAll('button, a[href]'))
    focusables()[0]?.focus()
    const onKey = (e) => {
      if (e.key === 'Escape') { setPanelShown(false); setTimeout(() => setGroupOpen(false), 300); return }
      if (e.key === 'Tab') {
        const list = focusables()
        const at = list.indexOf(document.activeElement)
        e.preventDefault()
        list[(at + (e.shiftKey ? -1 : 1) + list.length) % list.length]?.focus()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => {
      cancelAnimationFrame(id)
      window.removeEventListener('keydown', onKey)
      openerRef.current?.focus?.({ preventScroll: true })
    }
  }, [groupOpen])
  const closeGroup = () => { setPanelShown(false); setTimeout(() => setGroupOpen(false), 300) }

  useEffect(
    () => () => {
      gsap.killTweensOf(P.current)
      gsap.killTweensOf(S.current)
      chase.current.follow = false
    },
    [],
  )

  /* ---------- drag / swipe on the stage ---------- */
  const onPointerDown = (e) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return
    touch()
    gsap.killTweensOf(P.current)
    chase.current.target = P.current.pos
    chase.current.follow = true
    const hit = e.target.closest ? e.target.closest('[data-i]') : null
    const chip = e.target.closest ? e.target.closest('[data-tool]') : null
    drag.current = {
      on: true,
      moved: false,
      startX: e.clientX,
      startPos: P.current.pos,
      lastX: e.clientX,
      lastT: performance.now(),
      v: 0,
      downIdx: hit ? Number(hit.dataset.i) : null,
      downTool: chip ? chip.dataset.tool : null,
    }
    setDragging(true)
    stageRef.current.setPointerCapture?.(e.pointerId)
  }

  const onPointerMove = (e) => {
    const d = drag.current
    if (!d.on) return
    const dx = e.clientX - d.startX
    if (Math.abs(dx) > 4) d.moved = true
    if (!d.moved) return
    const now = performance.now()
    d.v = (e.clientX - d.lastX) / Math.max(1, now - d.lastT)
    d.lastX = e.clientX
    d.lastT = now
    chase.current.target = clamp(d.startPos - dx / geo.current.pitch, -0.35, N - 0.65)
  }

  const endDrag = (e) => {
    const d = drag.current
    if (!d.on) return
    d.on = false
    setDragging(false)
    stageRef.current.releasePointerCapture?.(e.pointerId)
    if (!d.moved) {
      if (d.downTool && d.downIdx === Math.round(P.current.pos)) {
        setSel(d.downTool)
        setGroupOpen(true)
        chase.current.follow = false
        return
      }
      goTo(d.downIdx != null ? d.downIdx : P.current.pos)
      return
    }
    // a faster flick travels further, up to two cards
    const flick = clamp((-d.v * 200) / geo.current.pitch, -2, 2)
    goTo(chase.current.target + flick)
  }

  const onKeyDown = (e) => {
    const cur = chase.current.goal
    touch()
    if (e.key === 'ArrowRight') { e.preventDefault(); goTo(cur + 1) }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); goTo(cur - 1) }
    else if (e.key === 'Home') { e.preventDefault(); goTo(0) }
    else if (e.key === 'End') { e.preventDefault(); goTo(N - 1) }
    else if (e.key === 'Enter') { e.preventDefault(); openerRef.current = e.currentTarget; setGroupOpen(true) }
    else if (/^[1-9]$/.test(e.key) && Number(e.key) <= N) { e.preventDefault(); goTo(Number(e.key) - 1) }
  }

  /* ---------- scrub the tick bar ---------- */
  const tickIndexAt = (x) => {
    const r = tickRef.current.getBoundingClientRect()
    return clamp(Math.floor(((x - r.left) / r.width) * N), 0, N - 1)
  }
  const onTickDown = (e) => {
    touch()
    tickDrag.current = { on: true, last: tickIndexAt(e.clientX) }
    setScrubbing(true)
    tickRef.current.setPointerCapture?.(e.pointerId)
    goTo(tickDrag.current.last, { duration: 0.8 })
  }
  const onTickMove = (e) => {
    const t = tickDrag.current
    if (!t.on) return
    const i = tickIndexAt(e.clientX)
    if (i !== t.last) {
      t.last = i
      goTo(i, { duration: 0.6 })
    }
  }
  const onTickUp = (e) => {
    tickDrag.current.on = false
    setScrubbing(false)
    tickRef.current.releasePointerCapture?.(e.pointerId)
  }

  /* ---------- copy the whole stack as text ---------- */
  const copyStack = async () => {
    const text = STACK.map((g) => `${g.title}: ${g.items.map((it) => it.name).join(', ')}`).join('\n')
    try {
      await navigator.clipboard.writeText(text)
      setCopied('Copied')
    } catch (err) {
      try {
        const ta = document.createElement('textarea')
        ta.value = text
        ta.style.position = 'fixed'
        ta.style.opacity = '0'
        document.body.appendChild(ta)
        ta.select()
        const ok = document.execCommand('copy')
        document.body.removeChild(ta)
        setCopied(ok ? 'Copied' : 'Copy blocked')
      } catch (e2) {
        setCopied('Copy blocked')
      }
    }
    setTimeout(() => setCopied(''), 1800)
  }

  const group = STACK[active]
  const hits = q ? STACK.reduce((n, g) => n + g.items.filter((it) => it.name.toLowerCase().includes(q)).length, 0) : 0
  const pickGroup = (i) => {
    goTo(i)
    setIndexOpen(false)
  }

  return (
    <section
      id="tech-stack"
      className="ts"
      ref={rootRef}
      aria-label="Tech stack"
      style={{ '--ga': group.tint }}
      onPointerEnter={() => { hoverRef.current = true }}
      onPointerLeave={() => { hoverRef.current = false; fx.current.hover = null }}
      onPointerOver={(e) => { const el = e.target.closest ? e.target.closest('[data-tool]') : null; fx.current.hover = el ? el.dataset.tool : null }}
    >
      <style>{CSS}</style>
      <a className="ts-skip" href="#work">Skip tech stack</a>

      {/* readable-as-text copy for screen readers and search engines */}
      <div className="ts-sr">
        <p aria-live="polite">
          Showing {group.title}, group {active + 1} of {N}. {group.items.length} tools.
        </p>
        <ul>
          {STACK.map((g) => (
            <li key={g.id}>
              <strong>{g.title}</strong>: {g.items.map((it) => `${it.name} (${LEVELS[it.level].label})`).join(', ')}
            </li>
          ))}
        </ul>
      </div>

      {/* atmosphere */}
      <div className="ts-bg" aria-hidden="true" ref={bgRef}>
        <div className="ts-glow" />
        <div className="ts-nebula" />
        <div className="ts-gridfloor" />
        <div className="ts-bgmark" key={group.id}><ToolLogo name={group.lead} className="ts-logo" /></div>
        <BackgroundFX fx={fx} related={relatedTools} />
        <span className="ts-shoot" />
        <span className="ts-shoot ts-shoot--b" />
        <span className="ts-ray ts-ray--c" />
        <span className="ts-ray ts-ray--l1" />
        <span className="ts-ray ts-ray--r1" />
        <span className="ts-ray ts-ray--l2" />
        <span className="ts-ray ts-ray--r2" />
        <div className="ts-grain" />
      </div>

      {/* intro: big heading like the Work section */}
      <div className="ts-intro">
        <h2 className="ts-intro__h">Tech Stack</h2>
        <p className="ts-intro__p">The languages, libraries and tools I use to turn data into working products. Pick a group, then a tool to see where I have used it.</p>
        <span className="ts-label__stats" aria-hidden="true">{N} groups · {TOTAL_TOOLS} tools · {PROJECT_COUNT} shipped projects</span>
      </div>

      {/* top bar: search, copy */}
      <div className="ts-label">
        <div className="ts-label__right">
          <span className={`ts-label__hint${used ? ' is-gone' : ''}`} aria-hidden="true">Drag, swipe or use the arrow keys</span>
          <div className="ts-search">
            <Icon><circle cx="11" cy="11" r="6" /><path d="m20 20-4.5-4.5" /></Icon>
            <input
              id="ts-search"
              type="search"
              value={query}
              placeholder="Find a tool"
              aria-label="Find a tool in the tech stack"
              autoComplete="off"
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Escape') setQuery('')
                e.stopPropagation()
              }}
            />
            {q && <span className="ts-search__n" aria-live="polite">{hits ? `${hits} found` : 'No match'}</span>}
          </div>
          <button type="button" className="ts-iconbtn ts-copy" onClick={copyStack} aria-label="Copy the whole stack as text" title="Copy the stack as text">
            {copied ? <span className="ts-copy__t">{copied}</span> : (
              <Icon><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M5 15V6a2 2 0 0 1 2-2h8" /></Icon>
            )}
          </button>
        </div>
      </div>

      {/* tool dock (desktop): every tool of the active group with its level */}
      <aside className="ts-dock" aria-label={`${group.title} tools`}>
        <div className="ts-dock__head">
          <div className="ts-seg" role="group" aria-label="Filter by level">
            {['all', 'core', 'strong', 'learning'].map((f) => (
              <button key={f} type="button" className={filter === f ? 'is-on' : ''} aria-pressed={filter === f} onClick={() => setFilter(f)}>
                {f === 'all' ? 'All' : LEVELS[f].label}
              </button>
            ))}
          </div>
        </div>
        <ul className="ts-dock__list" key={group.id}>
          {group.items.map((it, k) => (
            <li key={it.name} style={{ '--i': k }}>
              <button
                type="button"
                data-tool={it.name}
                className={`ts-dock__item${sel === it.name ? ' is-sel' : ''}${passes(it) ? '' : ' is-dim'}${q && passes(it) ? ' is-hit' : ''}`}
                onClick={(e) => { setSel(it.name); openerRef.current = e.currentTarget; setGroupOpen(true) }}
                aria-pressed={sel === it.name}
              >
                <ToolLogo name={it.name} className="ts-logo ts-dock__logo" />
                <span className="ts-dock__name">{it.name}</span>
                {USED[it.name].length > 0 && <span className="ts-dock__used" title="Used in a shipped project">{USED[it.name].length}</span>}
                <Meter level={it.level} />
              </button>
            </li>
          ))}
        </ul>
      </aside>

      {/* the curved carousel */}
      <div
        className={`ts-stage${dragging ? ' is-dragging' : ''}`}
        ref={stageRef}
        role="group"
        aria-roledescription="carousel"
        aria-label="Tech stack groups"
        tabIndex={0}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onKeyDown={onKeyDown}
      >
        <div className="ts-floor" aria-hidden="true" />
        <div className="ts-ring" ref={ringRef}>
          {STACK.map((g, i) => (
            <article
              key={g.id}
              className={`ts-card${i === active ? ' is-active' : ''}`}
              data-i={i}
              data-look={i % 4}
              ref={(el) => { cardsRef.current[i] = el }}
              style={{ '--tint': g.tint }}
              aria-hidden="true"
            >
              <div className="ts-card__body">
              <div className="ts-card__halo" />
              <div className="ts-card__face">
                <div className="ts-card__art" style={{ backgroundImage: arts[i] ? `url(${arts[i]})` : 'none' }} />
                <div className="ts-card__emblem"><ToolLogo name={g.lead} className="ts-logo" /></div>
                <div className="ts-card__num" aria-hidden="true">{pad(i + 1)}</div>
                <div className="ts-card__top">
                  <span>{g.kind}</span>
                </div>
                <div className="ts-card__title">{g.title}</div>

                <div className="ts-info">
                  <div className="ts-info__row ts-info__row--name">
                    <T className="ts-info__v" t={g.title} />
                  </div>
                  <div className="ts-info__row">
                    <T className="ts-info__k" t="Type:" />
                    <T className="ts-info__v" t={g.kind} />
                  </div>
                  <div className="ts-info__row">
                    <T className="ts-info__k" t="Items:" />
                    <T className="ts-info__v" t={pad(g.items.length)} />
                  </div>
                  {GROUP_PROJECTS[i].length > 0 && (
                    <div className="ts-info__row">
                      <T className="ts-info__k" t="Shipped:" />
                      <T className="ts-info__v" t={`${GROUP_PROJECTS[i].length} project${GROUP_PROJECTS[i].length > 1 ? 's' : ''}`} />
                    </div>
                  )}
                  <div className="ts-info__row ts-info__row--stack">
                    <T className="ts-info__k" t="Stack:" />
                    <div className="ts-info__list">
                      {g.items.map((it, k) => (
                        <span
                          key={it.name}
                          className={`ts-chip${sel === it.name && i === active ? ' is-sel' : ''}${i === active && !passes(it) ? ' is-dim' : ''}${i === active && q && passes(it) ? ' is-hit' : ''}`}
                          data-tool={it.name}
                          style={{ '--i': k }}
                        >
                          <ToolLogo name={it.name} className="ts-logo ts-chip__logo" />
                          <T t={it.name} />
                        </span>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="ts-card__sweep" />
                <div className="ts-card__glow" />
              </div>
              </div>
            </article>
          ))}
        </div>
      </div>

      {/* headline */}
      <div className="ts-head" ref={headRef} aria-hidden="true">
        <h3 className="ts-head__title">
          <span className="ts-head__mask">
            <span className="ts-head__line">
              <Arrow />
              <span>{group.title}</span>
            </span>
          </span>
        </h3>
        <p className="ts-head__desc">{group.blurb}</p>
      </div>

      <a className="ts-cta" href="#work">
        See what I built
        <Icon d="M5 12h14M13 6l6 6-6 6" />
      </a>

      <span className={`ts-hint${used ? ' is-gone' : ''}`} aria-hidden="true">Swipe to explore</span>

      {/* index button + pagination */}
      <button
        type="button"
        ref={pillRef}
        className={`ts-pill${indexOpen ? ' is-open' : ''}`}
        onClick={() => setIndexOpen(true)}
        aria-haspopup="dialog"
      >
        Index
        <Icon><path d="M3 6h18" /><path d="M3 12h12" /><path d="M3 18h7" /></Icon>
      </button>

      <nav className="ts-pager" aria-label="Tech stack navigation">
        <button type="button" className="ts-iconbtn" onClick={() => { touch(); step(-1) }} disabled={active === 0} aria-label="Previous group">
          <Icon d="m15 6-6 6 6 6" />
        </button>
        <span className="ts-pager__count ts-roll" key={`a${active}`} aria-hidden="true">{pad(active + 1)}</span>
        <div
          className={`ts-pager__items${scrubbing ? ' is-dragging' : ''}`}
          ref={tickRef}
          role="toolbar"
          aria-orientation="horizontal"
          aria-label="Groups"
          onPointerDown={onTickDown}
          onPointerMove={onTickMove}
          onPointerUp={onTickUp}
          onPointerCancel={onTickUp}
        >
          {STACK.map((g, i) => (
            <button
              key={g.id}
              type="button"
              className={`ts-tick${i === active ? ' is-active' : ''}`}
              aria-label={`Group ${i + 1}: ${g.title}`}
              aria-current={i === active ? 'true' : undefined}
              tabIndex={i === active ? 0 : -1}
              onClick={() => goTo(i)}
            >
              <span className="ts-tick__bar" />
            </button>
          ))}
        </div>
        <span className="ts-pager__count" aria-hidden="true">{pad(N)}</span>
        <button type="button" className="ts-iconbtn" onClick={() => { touch(); step(1) }} disabled={active === N - 1} aria-label="Next group">
          <Icon d="m9 6 6 6-6 6" />
        </button>
        <button
          type="button"
          className={`ts-iconbtn ts-auto${auto ? ' is-on' : ''}`}
          onClick={() => setAuto((v) => !v)}
          aria-pressed={auto}
          aria-label={auto ? 'Pause autoplay' : 'Play automatically'}
          title={auto ? 'Pause autoplay' : 'Play automatically'}
        >
          {auto ? <Icon><path d="M8 5v14M16 5v14" /></Icon> : <Icon d="M7 5l12 7-12 7z" />}
        </button>
      </nav>

      {groupOpen && (
        <div className={`ts-ov${panelShown ? ' is-show' : ''}`} ref={ovRef} role="dialog" aria-modal="true" aria-label={`${group.title} in detail`} style={{ '--tint': group.tint }}>
          <button type="button" className="ts-ov__bg" tabIndex={-1} aria-label="Close" onClick={closeGroup} />
          <div className="ts-panel">
            <button type="button" className="ts-panel__x" aria-label="Close" onClick={closeGroup}>✕</button>
            <div className="ts-panel__l">
              <span className="ts-panel__k">{pad(active + 1)} · {group.kind}</span>
              <h3 className="ts-panel__h">{group.title}</h3>
              <p className="ts-panel__d">{group.blurb}.</p>
              <div className="ts-panel__mix" aria-label="Level mix">
                {Object.keys(LEVELS).map((lv) => {
                  const c = group.items.filter((it) => it.level === lv).length
                  return c ? <span key={lv} className="ts-pill2">{c} {LEVELS[lv].label}</span> : null
                })}
              </div>
              {GROUP_PROJECTS[active].length > 0 && (
                <>
                  <span className="ts-panel__lb">Built with this group</span>
                  <div className="ts-panel__proj">
                    {GROUP_PROJECTS[active].map((p) => (
                      <a key={p.id} className="ts-shot" href={p.href || '#work'} target={p.href ? '_blank' : undefined} rel="noreferrer">
                        {p.image && <img src={p.image} alt="" loading="lazy" />}
                        <span className="ts-shot__t">{p.title}<span aria-hidden="true">↗</span></span>
                      </a>
                    ))}
                  </div>
                </>
              )}
            </div>
            <ul className="ts-panel__r">
              {group.items.map((it, k) => (
                <li key={it.name} className="ts-trow" style={{ '--i': k }}>
                  <span className="ts-trow__logo"><ToolLogo name={it.name} className="ts-logo" /></span>
                  <div className="ts-trow__main">
                    <span className="ts-trow__name">{it.name}</span>
                    <span className="ts-trow__note">{it.note}</span>
                    {USED[it.name].length > 0 && (
                      <span className="ts-trow__used">
                        {USED[it.name].map((p) => <span key={p.id} className="ts-pill2 ts-pill2--hot">{p.title}</span>)}
                      </span>
                    )}
                  </div>
                  <span className="ts-trow__lv"><Meter level={it.level} /><span>{LEVELS[it.level].label}</span></span>
                </li>
              ))}
            </ul>
          </div>
        </div>
      )}

      {indexOpen && (
        <div className="ts-index" role="dialog" aria-modal="true" aria-label="All tech stack groups">
          <button type="button" className="ts-index__backdrop" tabIndex={-1} aria-label="Close index" onClick={() => setIndexOpen(false)} />
          <div className={`ts-index__panel${indexMode === 'grid' ? ' is-grid' : ''}`} ref={panelRef}>
            <div className="ts-index__bar">
              <span className="ts-index__title">All groups</span>
              <div className="ts-seg" role="group" aria-label="Index layout">
                <button type="button" className={indexMode === 'list' ? 'is-on' : ''} aria-pressed={indexMode === 'list'} onClick={() => setIndexMode('list')}>List</button>
                <button type="button" className={indexMode === 'grid' ? 'is-on' : ''} aria-pressed={indexMode === 'grid'} onClick={() => setIndexMode('grid')}>Show all</button>
              </div>
              <button type="button" className="ts-iconbtn" aria-label="Close index" onClick={() => setIndexOpen(false)}>
                <Icon d="M6 6l12 12M18 6 6 18" />
              </button>
            </div>
            {indexMode === 'list' ? (
              <ol>
                {STACK.map((g, i) => (
                  <li key={g.id} style={{ '--tint': g.tint }}>
                    <button type="button" className={i === active ? 'is-active' : ''} onClick={() => pickGroup(i)}>
                      <span className="ts-index__n">{pad(i + 1)}</span>
                      <span className="ts-index__main">
                        <span className="ts-index__t">{g.title}</span>
                        <span className="ts-index__logos" aria-hidden="true">
                          {g.items.slice(0, 6).map((it) => <ToolLogo key={it.name} name={it.name} className="ts-logo" />)}
                        </span>
                      </span>
                      <span className="ts-index__c">{pad(g.items.length)}</span>
                    </button>
                  </li>
                ))}
              </ol>
            ) : (
              <div className="ts-grid">
                {STACK.map((g, i) => (
                  <button key={g.id} type="button" className={`ts-grid__tile${i === active ? ' is-active' : ''}`} style={{ '--tint': g.tint }} onClick={() => pickGroup(i)}>
                    <span className="ts-grid__h"><span className="ts-index__n">{pad(i + 1)}</span><span className="ts-index__t">{g.title}</span></span>
                    <span className="ts-grid__tools">
                      {g.items.map((it) => (
                        <span key={it.name} className="ts-grid__tool"><ToolLogo name={it.name} className="ts-logo" />{it.name}</span>
                      ))}
                    </span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </section>
  )
}
